from log_lane_audit import msi_cost_budget_evidence


class NativeBusRateEvidenceTests(unittest.TestCase):
    @staticmethod
    def sample(**changes):
        row = {'event':'input-capture-bus-rate-sample','dispatch':'direct-timer-callback',
               'rateFlags':0,'tickCount':120,'busySkips':0,'windowMs':1001,'expectedPublishHz':125,
               'excessiveCallbackRate':False,'pid':37,'powerGeneration':1,'writerProcessCreation100ns':'12345678901234567'}
        row.update(changes)
        return row

    def test_bus_terminal_and_msi_feedback_lanes_keep_physical_evidence(self):
        import warnings

        rate = 'input-capture-bus-rate'
        interruption = 'input-capture-bus-rate-boundary'
        feedback = 'msi-dinput-feedback'
        edge = self.sample(event=rate, previousRateFlags=2, state='recovered')
        boundary = self.sample(event=interruption, previousRateFlags=2, windowMs=2310,
                               windowInterruption='window-too-long', startReadyPowerGeneration=1,
                               endReadyPowerGeneration=1)
        managed_failure = dict(edge, event=feedback, managed=True, ok=False)
        managed_success = dict(managed_failure, ok=True)
        unmanaged = dict(managed_failure, managed=False)
        malformed = [dict(managed_failure, managed=1), dict(managed_failure, ok=0),
                     dict(managed_failure, ok=None), {'event': feedback, 'managed': True}]
        aliases = [{'kind': event, 'managed': True, 'ok': False} for event in (rate, interruption, feedback)]

        def wire(row):
            return (json.dumps(row) + '\r\n').encode('ascii')

        expected_resident = (edge, boundary, managed_failure)
        detail_cases = (self.sample(), managed_success, unmanaged, *malformed, *aliases)
        names = ('native-detail.log', 'native-detail.log.prev', 'native-detail.1.log', 'native-detail.1.log')
        with tempfile.TemporaryDirectory(prefix='ymcc-bus-feedback-lanes-') as root:
            path = Path(root) / 'bus-feedback.zip'
            with warnings.catch_warnings():
                warnings.simplefilter('ignore', UserWarning)
                with zipfile.ZipFile(path, 'w') as archive:
                    for name in (*names, 'nested/native-detail.log'):
                        archive.writestr(name, b'{partial\r\n' + b''.join(map(wire, (*expected_resident, *detail_cases))))
                    archive.writestr('native-lifecycle.log', b''.join(map(wire, (*expected_resident, *detail_cases[:3]))))
            result = audit_zip(path, {'baseEvents': [rate, interruption, feedback]})
        kind_by_event = {rate: 'bus-rate-transition-in-native-detail', interruption: 'bus-rate-boundary-in-native-detail',
                         feedback: 'msi-managed-feedback-failure-in-native-detail'}
        actual = [(v['file'], v['archiveEntryOccurrence'], v['kind'], v['event'], v['exampleLines'],
                   sum(bucket['bytes'] for bucket in v['nativeDetailFindingWriterFootprint']['buckets'].values()))
                  for v in result['violations'] if v['kind'] in kind_by_event.values()]
        self.assertCountEqual(actual, [(name, int(index == 3), kind_by_event[row['event']], row['event'], [line], len(wire(row)))
                                       for index, name in enumerate(names)
                                       for line, row in enumerate(expected_resident, 2)])
        self.assertCountEqual([(v['event'], v['exampleLines']) for v in result['violations']
                               if v['kind'] == 'known-detail-in-native-low'],
                              [('input-capture-bus-rate-sample', [4]), (feedback, [5, 6])])

    def test_samples_and_transitions_are_distinct_across_writer_lifetimes(self):
        from log_lane_audit import native_bus_rate_evidence
        sample = self.sample()
        enter = self.sample(event='input-capture-bus-rate',previousRateFlags=0,rateFlags=2,state='abnormal')
        change = self.sample(event=enter['event'],previousRateFlags=2,rateFlags=4,state='abnormal',
                             tickCount=253,excessiveCallbackRate=True)
        recover = self.sample(event=enter['event'],previousRateFlags=4,rateFlags=0,state='recovered',
                              writerProcessCreation100ns='12345678901234568')
        evidence = native_bus_rate_evidence([
            ('native-lifecycle.log', [(1,enter),(5,change),(8,recover)], {}),
            ('native-detail.log.1', [(2,sample),(3,self.sample(tickCount=0)),(4,self.sample(rateFlags=1,busySkips=3))], {}),
        ])
        self.assertEqual((evidence['observedSamples'],evidence['observedTransitions']), (3,3))
        self.assertEqual([v['kind'] for v in evidence['transitionCounts']], ['entered','category-changed','recovered'])
        self.assertEqual([(v['sampleRows'],v['transitionRows'],v['zeroCallbackSamples']) for v in evidence['writerPowerGroups']],
                         [(3,2,1),(0,1,0)])
        self.assertFalse(evidence['sampleToTransitionJoinProven'])
        self.assertFalse(evidence['completeTimeCoverageProven'])

    def test_rejected_records_and_unbound_rows_are_not_upgraded(self):
        from log_lane_audit import native_bus_rate_evidence
        samples = [self.sample(rateFlags=True), self.sample(dispatch='future'), self.sample(rateFlags=4),
                   self.sample(event='input-capture-bus-rate', previousRateFlags=0, state='recovered'),
                   self.sample(writerProcessCreation100ns=123)]
        value = native_bus_rate_evidence([('native-detail.log', list(enumerate(samples,1)), {})])
        self.assertEqual(value['unprojectedRows'], {'missing-or-invalid-window-fields':1,'unsupported-window-scope':1,
                                              'inconsistent-rate-flags':1,'invalid-transition':1})
        self.assertEqual(value['unboundRows'],1)
        self.assertEqual(value['unexpectedLaneRows'],1)
        self.assertEqual(value['writerPowerGroups'],[])
        self.assertEqual(value['sampleCounts'],[{'rateFlags':0,'kind':'nonzero-callback-window','count':1}])

    def test_root_carriers_and_bounded_writer_groups(self):
        from log_lane_audit import native_bus_rate_evidence
        sample = self.sample()
        value = native_bus_rate_evidence([
            ('steam/logs/native-detail.log',[(1,sample)],{}),
            ('native-detail.log',[(1,sample)],{'container':'nested.zip'}),
            ('native-detail.1.log',[(i,self.sample(powerGeneration=i)) for i in range(1,35)],{'archiveEntryOccurrence':2}),
        ])
        self.assertEqual(value['observedSamples'],34)
        self.assertEqual(len(value['writerPowerGroups']),32)
        self.assertEqual(value['writerPowerGroupLimitRows'],2)
        self.assertEqual(len(value['witnesses']),1)
        self.assertEqual(value['witnesses'][0]['archiveEntryOccurrence'],2)

    def test_zip_audit_keeps_sample_and_change_carriers_separate(self):
        sample = self.sample()
        edge = self.sample(event='input-capture-bus-rate',previousRateFlags=2,state='recovered')
        with tempfile.TemporaryDirectory() as folder:
            path = Path(folder) / 'bus.zip'
            with zipfile.ZipFile(path,'w') as archive:
                archive.writestr('native-detail.log.1', json.dumps(sample)+'\n')
                archive.writestr('native-lifecycle.log', json.dumps(edge)+'\n')
                archive.writestr('steam/logs/native-detail.log.1', json.dumps(sample)+'\n')
            value = audit_zip(path, {'baseEvents':[]})['commonEvidence']['nativeBusRateEvidence']
        self.assertEqual((value['observedSamples'],value['observedTransitions'],value['unexpectedLaneRows']), (1,1,0))
        self.assertEqual({v['file'] for v in value['witnesses']}, {'native-detail.log.1','native-lifecycle.log'})

    def test_interrupted_legacy_and_current_windows_do_not_count_as_recovery(self):
        from log_lane_audit import native_bus_rate_evidence
        recovery = self.sample(event='input-capture-bus-rate', previousRateFlags=2, state='recovered')
        boundary = self.sample(event='input-capture-bus-rate-boundary', previousRateFlags=2,
                               windowInterruption='power-context-changed', startReadyPowerGeneration=1,
                               endReadyPowerGeneration=0, windowMs=21640747, powerLifecycle='suspended')
        sample = self.sample(windowInterruption='window-too-long', windowMs=742663)
        evidence = native_bus_rate_evidence([
            ('native-lifecycle.log', [(1, dict(recovery, windowMs=742663)),
                                     (2, dict(recovery, powerLifecycle='resuming')),
                                     (3, boundary), (4, recovery),
                                     (5, dict(boundary, endReadyPowerGeneration=1))], {}),
            ('native-detail.log', [(1, sample)], {}),
        ])
        self.assertEqual(evidence['transitionCounts'], [{'previousRateFlags': 2, 'rateFlags': 0, 'kind': 'recovered', 'count': 1}])
        self.assertEqual(evidence['observedBoundaries'], 2)
        self.assertEqual(evidence['sampleCounts'], [])
        self.assertEqual(evidence['unprojectedRows'], {'invalid-window-interruption': 1})
        self.assertEqual([(row['carrier'], row['reason'], row['count']) for row in evidence['interruptionCounts']], [
            ('boundary', 'power-context-changed', 1), ('legacy-transition', 'legacy-power-not-ready', 1),
            ('legacy-transition', 'legacy-window-too-long', 1), ('sample', 'window-too-long', 1)])
        self.assertEqual([(v['carrier'], v['first']['line']) for v in
                         evidence['interruptionWriterPowerGroups'][0]['counts']],
                         [('boundary', 3), ('legacy-transition', 2), ('legacy-transition', 1), ('sample', 1)])

    def test_bus_interruptions_keep_row_context_and_actual_lane(self):
        from log_lane_audit import native_bus_rate_evidence
        sample = self.sample(powerGeneration=2, windowInterruption='power-context-changed')
        boundary = dict(sample, event='input-capture-bus-rate-boundary', previousRateFlags=0,
                        startReadyPowerGeneration=1, endReadyPowerGeneration=0)
        value = native_bus_rate_evidence([
            ('native-lifecycle.log', [(8,boundary), (9,sample)], {'archiveEntryOccurrence':1}),
            ('native-detail.log', [(21,sample), (22,sample),
                                   (23,dict(sample, writerProcessCreation100ns='12345678901234568')),
                                   (24,dict(sample, powerGeneration=3))], {'archiveEntryOccurrence':2}),
            ('nativeXdetail.log', [(1,sample)], {}),
            ('native-detailXlog', [(1,sample)], {}),
        ])
        groups = value.get('interruptionWriterPowerGroups', [])
        self.assertEqual([(g['pid'], g['writerProcessCreation100ns'], g['powerGeneration']) for g in groups],
                         [(37,'12345678901234567',2), (37,'12345678901234568',2), (37,'12345678901234567',3)])
        self.assertEqual(groups[0]['counts'], [
            dict(carrier='boundary', physicalLane='lifecycle', reason='power-context-changed', count=1,
                 first=dict(file='native-lifecycle.log', line=8, archiveEntryOccurrence=1,
                            startReadyPowerGeneration=1, endReadyPowerGeneration=0)),
            dict(carrier='sample', physicalLane='detail', reason='power-context-changed', count=2,
                 first=dict(file='native-detail.log', line=21, archiveEntryOccurrence=2)),
            dict(carrier='sample', physicalLane='lifecycle', reason='power-context-changed', count=1,
                 first=dict(file='native-lifecycle.log', line=9, archiveEntryOccurrence=1)),
        ])
        self.assertEqual(value['unexpectedLaneRows'], 1)
        self.assertEqual((value['sampleCounts'], value['transitionCounts'], value['writerPowerGroups']), ([], [], []))

    def test_bus_interruption_budget_and_missing_identity_do_not_hide_totals(self):
        from log_lane_audit import native_bus_rate_evidence
        sample = self.sample(windowInterruption='window-too-long', windowMs=2001)
        rows = [dict(sample, powerGeneration=i) for i in range(34)]
        rows += [sample, dict(sample, writerProcessCreation100ns='0'), dict(sample, pid=True),
                 dict(sample, powerGeneration=None), dict(sample, windowMs=2000), self.sample(powerGeneration=34)]
        value = native_bus_rate_evidence([('native-detail.log', list(enumerate(rows, 1)), {})])
        self.assertEqual(value['interruptionCounts'], [dict(carrier='sample', reason='window-too-long', count=38)])
        self.assertEqual(value['interruptionUnboundRows'], 3)
        self.assertEqual(value['interruptionWriterPowerGroupLimitRows'], 2)
        self.assertEqual(len(value['interruptionWriterPowerGroups']), value['writerPowerGroupLimit'])
        self.assertEqual(value['interruptionWriterPowerGroups'][1]['counts'][0]['count'], 2)
        self.assertEqual(value['unprojectedRows'], {'invalid-window-interruption':1})
        self.assertEqual(value['unboundRows'], 0)
        self.assertEqual(value['writerPowerGroupLimitRows'], 0)
        self.assertEqual([g['powerGeneration'] for g in value['writerPowerGroups']], [34])

    def test_compact_samples_restore_scope_without_upgrading_unknown_records(self):
        from log_lane_audit import native_bus_rate_evidence
        full = self.sample(highRateThresholdMultiplier=2)
        compact = dict(full, busRateSampleScope=1)
        del compact['dispatch'], compact['highRateThresholdMultiplier']
        def audit(rows):
            return native_bus_rate_evidence([('native-detail.log', list(enumerate(rows, 1)), {})])
        self.assertEqual(audit([compact]), audit([full]))
        self.assertEqual(audit([dict(full, busRateSampleScope=1)]), audit([full]))
        legacy = dict(compact); del legacy['busRateSampleScope']
        bad = [legacy, dict(compact, busRateSampleScope=True), dict(compact, busRateSampleScope=2),
               dict(compact, highRateThresholdMultiplier=2.0), dict(compact, dispatch='future'),
               dict(compact, event='input-capture-bus-rate', previousRateFlags=2, state='recovered')]
        observed = audit(bad + [compact])
        self.assertEqual(observed['unprojectedRows'], {'unsupported-window-scope':len(bad)})
        self.assertEqual(observed['sampleCounts'], audit([full])['sampleCounts'])
        self.assertEqual(observed['transitionCounts'], [])


class MsiCostBudgetEvidenceTests(unittest.TestCase):
    POLICY = 'VC-MSI-COST-LOG-BUDGET-20261024-R1'

    @classmethod
    def window(cls, version=2):
        return {'writerPid': 19, 'frames': 30, 'msiCostWindowDeferred':
                {'version': version, 'logBudgetPolicy': cls.POLICY, 'recordMaxBytes': 16384}}

    @classmethod
    def bulk(cls, version, size, **overrides):
        return {**cls.window(version), 'steamDeckPadSubmissions': None, 'usbipTransport': None,
                'diagnosticBudget': {'schemaVersion': version, 'policy': cls.POLICY,
                    'state': 'bulk-evidence-omitted', 'recordMaxBytes': 16384,
                    'completePayloadRetained': False, 'originalRecordBytes': size,
                    'omittedFields': ['steamDeckPadSubmissions', 'usbipTransport'], **overrides}}

    @classmethod
    def summary(cls, kind, **overrides):
        return {'writerPid': 19, 'kind': kind, 'capturedFrames': 30,
                'diagnosticBudget': {'schemaVersion': 1, 'policy': cls.POLICY,
                    'state': kind, 'recordMaxBytes': 16384, 'completePayloadRetained': False,
                    'identityTextMayBeTruncated': True, 'originalRecordBytes': None, **overrides}}

    def test_legacy_and_current_budget_remain_distinct_from_worker_failure(self):
        bulk = self.bulk(1, 18424)
        bulk['usbipTransportSummary'] = {'snapshot': None}
        bulk['steamDeckPadSubmissionSummary'] = None
        failure = self.summary('cost-window-failed', reason='append', failedWindows=67)
        summary = self.summary('cost-window-summary', originalRecordBytes=50000, reason='non-bulk-metadata-over-budget')
        data = (self.window(), bulk, self.bulk(2, 35550, oversizedWindows=3857), failure,
                summary, self.summary('cost-window-failed', reason=['not-a-known-stage']))
        view = msi_cost_budget_evidence('input-host-cost.log', enumerate(data, 1))
        self.assertEqual(view['rowsByState'], {'window-without-budget-receipt': 1, 'bulk-evidence-omitted': 2,
                                              'cost-window-summary': 1, 'cost-window-failed': 2})
        self.assertEqual(view['firstReceiptLines'], {'bulk-evidence-omitted': 2, 'cost-window-failed': 4, 'cost-window-summary': 5})
        self.assertEqual(view['failureStages'], {'append': 1, 'unknown-stage': 1})
        self.assertEqual(view['largestReportedOriginalRecords'], {'bulk-evidence-omitted': {'line': 3, 'originalRecordBytes': 35550},
                                                                 'cost-window-summary': {'line': 5, 'originalRecordBytes': 50000}})
        self.assertEqual(view['bulkSummaryShapes'], {'usbipTransportSummary': {'object-retained': 1, 'absent': 1},
                                                     'steamDeckPadSubmissionSummary': {'non-object': 1, 'absent': 1}})

    def test_missing_unsupported_and_inconsistent_receipts_do_not_supply_counts(self):
        missing = self.summary('cost-window-summary'); del missing['diagnosticBudget']
        earlier = self.bulk(2, 35550); earlier['usbipTransport'] = {}
        premature = self.summary('cost-window-failed', originalRecordBytes=19000)
        unsupported_summary = self.summary('cost-window-summary', schemaVersion=2)
        data = (missing, earlier, premature, unsupported_summary, self.bulk(True, 19000),
                self.bulk(2, 16384), self.bulk(2, 19000, policy='unknown'), self.bulk(1, 19000, omittedFields='unknown'),
                {'kind': 'usbip-transport-lifecycle'}, {'frames': 3}, {'diagnosticBudget': None})
        view = msi_cost_budget_evidence('input-host-cost.log.1', enumerate(data, 1))
        self.assertEqual(view['rowsByState'], {'missing-budget-receipt': 1, 'invalid-budget-receipt': 5,
                                             'unsupported-budget-receipt': 3})
        self.assertEqual(view['firstReceiptLines'], {})
        self.assertEqual(view['largestReportedOriginalRecords'], {})
        self.assertIsNone(msi_cost_budget_evidence('input-host-cost.log.pending', enumerate(data, 1)))

    def test_same_row_identity_requires_version_and_complete_coherent_root(self):
        from log_lane_audit import msi_cost_deferred_window_identity
        good = self.bulk(2, 35550)
        identity = {'hostInstanceId': 'host-a', 'epoch': 0, 'powerGeneration': (1 << 64) - 1}
        good.update(identity, runId='')
        good['msiCostWindowDeferred'].update(version=3, runId=None)
        expected = {'state': 'reported-same-row-identity', 'reported': identity}
        self.assertEqual(msi_cost_deferred_window_identity(good), expected)
        self.assertIsNone(good['msiCostWindowDeferred']['runId'])
        self.assertTrue(good['msiCostWindowDeferred'].keys().isdisjoint(identity))
        mixed = dict(good, msiCostWindowDeferred=dict(good['msiCostWindowDeferred'], epoch=0))
        missing = dict(good); del missing['powerGeneration']
        invalid = [missing, dict(good, runId='different'), dict(good, epoch=False),
                   dict(good, powerGeneration=1 << 64), dict(good, kind='cost-window-failed')]
        legacy = self.bulk(2, 35551)
        self.assertIsNone(msi_cost_deferred_window_identity(legacy))
        ordinary = dict(good); del ordinary['diagnosticBudget']
        data = [good, ordinary, mixed, *invalid, legacy]
        view = msi_cost_budget_evidence('input-host-cost.log.1', enumerate(data, 1))
        self.assertEqual(view['deferredWindowIdentityRowsByState'], {'reported-same-row-identity': 2,
            'mixed-inline-identity': 1, 'invalid-window-identity': len(invalid)})
        self.assertEqual(view['rowsByState'], {'window-without-budget-receipt': 1,
            'bulk-evidence-omitted': 2, 'invalid-budget-receipt': len(invalid) + 1})

    def test_zip_keeps_budget_views_per_root_member_and_ignores_other_carriers(self):
        ordinary = json.dumps(self.window()) + '\n'
        bulk = json.dumps(self.bulk(2, 18000)) + '\n'
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp)/'capsule.zip'
            with zipfile.ZipFile(path, 'w') as archive:
                archive.writestr('input-host-cost.log', ordinary)
                archive.writestr('input-host-cost.log.1', bulk)
                archive.writestr('input-host-fatal.log', bulk)
                archive.writestr('steam/input-host-cost.log', bulk)
            before = path.read_bytes()
            audit = audit_zip(path, {'baseEvents': set()})
            self.assertEqual(path.read_bytes(), before)
        projected = {entry['file']:entry['msiCostBudgetEvidence']['rowsByState'] for entry in audit['files']
                     if 'msiCostBudgetEvidence' in entry}
        self.assertEqual(projected, {'input-host-cost.log': {'window-without-budget-receipt': 1},
                                     'input-host-cost.log.1': {'bulk-evidence-omitted': 1}})


class HostSignalWriterEvidenceTests(unittest.TestCase):
    HOST = 'a' * 32

    @classmethod
    def row(cls, *, host=None, signal=None, shared=None, tail=False):
        return {'schema':1, 'kind':'host-virtual-signal-tail' if tail else 'host-virtual-signal',
                'deferredQueueAdmission':True, 'request':{'hostInstanceId':host or cls.HOST, 'bindingTextTruncated':False},
                'logWriter':{'version':1, 'snapshotAtomic':False, 'workerStopped':False,
                             'sharedQueue':shared or {}, **(signal or {})}}

    def test_shared_drops_never_supply_signal_loss_and_host_instances_stay_separate(self):
        rows = [(1, self.row(signal={'rejected':0, 'written':3}, shared={'Dropped':532, 'DroppedFull':532})),
                (2, self.row(signal={'rejected':2, 'failed':1}, shared={'Dropped':2}, tail=True)),
                (3, self.row(host='b'*32, signal={'rejected':0}, shared={'Dropped':0})),
                (4, self.row(signal={'rejected':0, 'unfinished':2}, shared={'Dropped':533}))]
        view = host_signal_writer_evidence('input-host-signal.log.prev', rows)
        self.assertEqual(view['rowsByStatus'], {'projected':4})
        first, second = view['instances']
        self.assertEqual(first['rowsByKind'], {'host-virtual-signal':2, 'host-virtual-signal-tail':1})
        witnesses = {item['line']: item for item in first['observations']}
        self.assertEqual(witnesses[1]['sharedQueue']['Dropped'], 532)
        self.assertEqual(witnesses[1]['signalWriter']['rejected'], 0)
        self.assertIn('latest-signal-loss-witness', witnesses[2]['roles'])
        self.assertNotIn('latest-signal-loss-witness', witnesses[4]['roles'])
        self.assertIn('latest-shared-queue-loss-witness', witnesses[4]['roles'])
        self.assertEqual([item['line'] for item in second['observations']], [3])

    def test_invalid_and_legacy_values_remain_unknown_and_discard_has_conditions(self):
        bare = self.row(); bare.pop('deferredQueueAdmission'); bare.pop('logWriter')
        unavailable = self.row(); unavailable['logWriter'] = None
        unknown = self.row(signal={'version':True})
        clipped = self.row(); clipped['request']['bindingTextTruncated'] = True
        torn = self.row(signal={'rejected':False, 'invalid':-1, 'failed':float(0), 'flagDisabled':1<<63,
                                'discardedOnClose':5, 'workerStopped':False}, shared={'Dropped':True})
        close = self.row(signal={'workerStopped':True, 'admissionInProgress':0, 'unfinished':5, 'discardedOnClose':5})
        view = host_signal_writer_evidence('input-host-signal.log', list(enumerate((bare, unavailable, unknown, clipped, torn, close), 1)))
        self.assertEqual(view['rowsByStatus'], {'deferred-writer-not-observed':1, 'writer-not-observed':1,
            'unsupported-writer-schema':1, 'unbound-host-instance':1, 'projected':2})
        before, after = view['instances'][0]['observations']
        self.assertTrue(all(value is None for value in before['signalWriter'].values()))
        self.assertIsNone(before['sharedQueue']['Dropped'])
        self.assertEqual(after['signalWriter']['discardedOnClose'], 5)

    def test_instance_capacity_reports_unclassified_rows_without_affecting_retained_instances(self):
        rows = [(i+1, self.row(host=f'{i:032x}')) for i in range(HOST_SIGNAL_WRITER_MAX_INSTANCES+1)]
        rows.append((len(rows)+1, self.row(host='0'*32, signal={'failed':1})))
        view = host_signal_writer_evidence('input-host-signal.log', rows)
        self.assertEqual(len(view['instances']), HOST_SIGNAL_WRITER_MAX_INSTANCES)
        self.assertEqual(view['rowsByStatus']['instance-capacity-omitted'], 1)
        self.assertEqual(view['instances'][0]['observations'][-1]['signalWriter']['failed'], 1)

    def test_compact_schema_is_cost_only_and_keeps_discard_and_binding_rules(self):
        signal = self.row(signal={'version':2, 'workerStopped':True, 'admissionInProgress':0,
                                  'discardedOnClose':5, 'unfinished':5}, shared={'Discarded':7})
        writer = signal['logWriter']
        cost = {'windowMs':1000, 'frames':60, 'writerPid':5, 'hostInstanceId':self.HOST}
        rows = [dict(cost, signalLogWriter=dict(writer, version=1, scope='legacy inline')),
                dict(cost, signalLogWriter=writer),
                dict(cost, signalLogWriter=dict(writer, admissionInProgress=1)),
                dict(cost, signalLogWriter=dict(writer, workerStopped=False)),
                dict(cost, signalLogWriter=dict(writer, snapshotAtomic=True)),
                dict(cost, signalLogWriter=dict(writer, version=3)),
                dict(cost, hostInstanceId='unbound', signalLogWriter=writer)]
        view = host_signal_writer_evidence('input-host-cost.log.1', list(enumerate(rows, 1)))
        self.assertEqual(view['rowsByStatus'], {'projected':4, 'unsupported-writer-schema':2, 'unbound-host-instance':1})
        before, compact, running = view['instances'][0]['observations']
        self.assertEqual(before['signalWriter'], compact['signalWriter'])
        self.assertEqual(before['sharedQueue'], compact['sharedQueue'])
        self.assertEqual(compact['signalWriter']['discardedOnClose'], 5)
        self.assertIn('latest-signal-loss-witness', compact['roles'])
        self.assertIsNone(running['signalWriter']['discardedOnClose'])
        admitting = host_signal_writer_evidence('input-host-cost.log', [(3, rows[2])])
        self.assertIsNone(admitting['instances'][0]['observations'][0]['signalWriter']['discardedOnClose'])
        self.assertEqual(host_signal_writer_evidence('input-host-signal.log', [(1, signal)])['rowsByStatus'],
                         {'unsupported-writer-schema':1})

    def test_actual_zip_audit_keeps_cost_signal_and_retained_occurrences_separate(self):
        signal = self.row(signal={'written':7}, shared={'Dropped':2})
        cost = {'windowMs':1000, 'frames':60, 'writerPid':5, 'hostInstanceId':self.HOST,
                'signalLogWriter':dict(signal['logWriter'], written=9)}
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp)/'capsule.zip'
            with zipfile.ZipFile(path, 'w') as zipped:
                zipped.writestr('input-host-signal.log', json.dumps(signal)+'\n')
                zipped.writestr('input-host-signal.log.prev', json.dumps(signal)+'\n')
                zipped.writestr('input-host-cost.log', json.dumps(cost)+'\n')
                compact_cost = dict(cost, signalLogWriter=dict(cost['signalLogWriter'], version=2))
                zipped.writestr('input-host-cost.log.prev', json.dumps(compact_cost)+'\n')
                zipped.writestr('steam/input-host-signal.log', json.dumps(signal)+'\n')
            preimage = path.read_bytes()
            result = audit_zip(path, {'baseEvents':set()})
            self.assertEqual(path.read_bytes(), preimage)
        entries = {entry['file']:entry['hostSignalWriterEvidence'] for entry in result['files']
                   if 'hostSignalWriterEvidence' in entry}
        self.assertEqual(set(entries), {'input-host-signal.log', 'input-host-signal.log.prev', 'input-host-cost.log', 'input-host-cost.log.prev'})
        self.assertEqual(entries['input-host-cost.log'], entries['input-host-cost.log.prev'])
        self.assertEqual(entries['input-host-signal.log'], entries['input-host-signal.log.prev'])
        self.assertEqual(entries['input-host-cost.log']['instances'][0]['observations'][0]['kind'], 'cost-window')
        self.assertEqual(entries['input-host-cost.log']['instances'][0]['observations'][0]['signalWriter']['written'], 9)


class FrontendOwnerTransitionTests(unittest.TestCase):
    @staticmethod
    def row(**extra):
        return {'where':'gamepad-admission','trace':dict(stage='owner-result',ownerTransitionSchema=1,phase='after-call',
            transition='start',trigger='window-focus',owner='none',epoch=0,rearm=True,sourceAdmission=False,sourcePresent=True,**extra)}
    @staticmethod
    def view(row):
        from log_lane_audit import frontend_owner_transition_record
        return frontend_owner_transition_record(row)
    def test_before_and_after_are_observations_not_success(self):
        row=self.row();after=self.view(row);self.assertEqual(after['state'],'after-call');self.assertTrue(after['callReturnedObserved']);self.assertEqual(after['ownerState']['owner'],'none');self.assertEqual(after['ownerState']['epoch'],0);self.assertFalse(after['nativeAdmissionProven'] or after['actionOrDeliveryProven'])
        row['trace'].update(stage='owner-start',phase='before-call');before=self.view(row);self.assertEqual(before['state'],'before-call');self.assertFalse(before['callReturnedObserved']);self.assertEqual(before['ownerState'],after['ownerState'])
    def test_old_missing_null_and_bad_schema_are_not_backfilled(self):
        row=self.row();row['trace'].pop('ownerTransitionSchema');row['trace'].pop('phase');self.assertEqual(self.view(row)['state'],'legacy-unversioned');self.assertIsNone(self.view(row)['ownerState'])
        row['trace']['ownerTransitionSchema']=None;self.assertEqual(self.view(row)['state'],'null-schema')
        for bad in [True,2,'1',{},[]]:row['trace']['ownerTransitionSchema']=bad;self.assertEqual(self.view(row)['state'],'unsupported-schema')
    def test_strict_phase_snapshot_and_stage_combinations(self):
        for key,bad in [('phase','done'),('transition','restart'),('stage','engine-stop'),('trigger','private-game'),('reason','made-up'),('owner','bad'),('epoch',True),('epoch',1.0),('epoch',1<<53),('rearm',0),('sourceAdmission',None),('sourcePresent','true')]:
            row=self.row();row['trace'][key]=bad;self.assertEqual(self.view(row)['state'],'invalid-fields',(key,bad))
        for transition in ['start','stop','summon','source-inserted','source-removed']:
            row=self.row();row['trace']['transition']=transition;self.assertEqual(self.view(row)['state'],'after-call')
        self.assertIsNone(self.view({'where':'other','trace':self.row()['trace']}));self.assertIsNone(self.view({'where':'gamepad-admission','trace':{'stage':[]}}))
    def test_private_payload_is_not_copied_or_mutated(self):
        row=self.row();row['trace']['private']='secret'*100000;before=json.dumps(row,sort_keys=True);view=self.view(row);self.assertEqual(json.dumps(row,sort_keys=True),before);self.assertNotIn('secret',json.dumps(view));self.assertLess(len(json.dumps(view)),1000)
    def test_fifty_thousand_rows_keep_fixed_witnesses_and_no_pair_inference(self):
        from log_lane_audit import frontend_owner_transition_evidence
        row=self.row();view=frontend_owner_transition_evidence((i,row) for i in range(50000));self.assertEqual(view['counts']['after-call'],50000);self.assertEqual(len(view['witnesses']),16);self.assertEqual(view['omittedWitnesses'],49984);self.assertFalse(view['missingAfterCallIsFailureProof']);self.assertLess(len(json.dumps(view)),12000)
    def test_actual_zip_dispatch_retains_original_bytes_and_phase_counts(self):
        with tempfile.TemporaryDirectory() as root:
            p=Path(root)/'owner.zip';after=self.row();before=self.row();before['trace'].update(stage='owner-start',phase='before-call');legacy={'where':'gamepad-admission','trace':{'stage':'owner-start','owner':'none','sourceAdmission':False}}
            data=b''.join((json.dumps(row)+'\n').encode() for row in [before,after,legacy])
            with zipfile.ZipFile(p,'w') as z:z.writestr('frontend-trace.log.previous',data)
            view=audit_zip(p,{'baseEvents':[]});entry=next(q for q in view['files'] if q['file']=='frontend-trace.log.previous');counts=entry['ownerTransitionEvidence']['counts'];self.assertEqual([counts[q] for q in ['before-call','after-call','legacy-unversioned']],[1,1,1]);self.assertTrue(view['memberReadCoverageComplete'])
            with zipfile.ZipFile(p) as z:self.assertEqual(z.read('frontend-trace.log.previous'),data)


