class QuarantineObservationTests(unittest.TestCase):
    @staticmethod
    def row(event='input-host-quarantine-endpoint-probe', **values):
        return {'event': event, 'pid': 37, 'powerGeneration': 9, 'connectedMask': 1,
                'virtualEndpointAbsent': False, **values}

    @staticmethod
    def repeats(rows, filename='native-lifecycle.log'):
        return repeated_quarantine_observations(list(enumerate(rows, 1)), filename)

    def test_quarantine_producers_and_absent_fields_remain_independent(self):
        bus = self.row()
        lifecycle = self.row(owner='capture-lifecycle-thread', busBlocking=False)
        candidate = {**lifecycle, 'ownedSdReturnCandidate': False}
        result = self.repeats([bus, lifecycle, bus, lifecycle, candidate, candidate])
        self.assertEqual([line for line, _ in result[bus['event']]], [3, 4, 6])
        self.assertNotIn('ownedSdReturnCandidate', lifecycle)
        self.assertIs(result[bus['event']][0][1], bus)

    def test_quarantine_full_wire_values_and_future_ownership_stay_semantic(self):
        base = self.row()
        states = [base, {**base, 'connectedMask': 3},
                  {**base, 'virtualEndpointAbsentScope': 'full-endpoint'},
                  {**base, 'virtualEndpointAbsent': 0},
                  {**base, 'virtualEndpointAbsent': 0.0},
                  {**base, 'unknown': {'nested': [False, {'x': 1}]}},
                  {**base, 'runId': 'r1', 'epoch': 1, 'hostInstanceId': 'h1'},
                  {**base, 'runId': 'r2', 'epoch': 1, 'hostInstanceId': 'h1'}]
        rows = [item for state in states for item in (state, dict(state))]
        result = self.repeats(rows)[base['event']]
        self.assertEqual([line for line, _ in result], list(range(2, 17, 2)))
        envelope = {**states[-1], 'time': 'later', 'hwnd': 1, 'powerLifecycle': 'Ready'}
        self.assertEqual(len(self.repeats([states[-1], envelope])[base['event']]), 1)

    def test_quarantine_generation_clear_boot_and_writer_boundaries(self):
        base = self.row()
        rows = [base, base, {**base, 'powerGeneration': 10}, base, base,
                self.row('input-host-quarantine-cleared'), base, base,
                self.row('boot-single-instance-acquired'), base, base,
                {**base, 'pid': 38}, {**base, 'pid': 38},
                {**base, 'writerProcessCreation100ns': '123'},
                {**base, 'writerProcessCreation100ns': '123'},
                {**base, 'writerProcessCreation100ns': '124'}]
        result = self.repeats(rows)[base['event']]
        self.assertEqual([line for line, _ in result], [2, 5, 8, 11, 13, 15])
        self.assertEqual(self.repeats([base, base], 'native-lifecycle.log.12')[base['event']][0][0], 2)
        for filename in ('virtual-gamepad.log', 'native-lifecycle-detail.log',
                         'steam/native-lifecycle.log', 'native-lifecycle.log.zip'):
            self.assertEqual(self.repeats([base, base], filename), {})

    def test_quarantine_unknown_and_invalid_boundaries_never_bridge_repeats(self):
        base = self.row()
        invalid = [{**base, 'pid': None}, {**base, 'pid': True},
                   {**base, 'powerGeneration': None}, {**base, 'powerGeneration': True},
                   {**base, 'powerGeneration': -1}, {**base, 'powerGeneration': 1 << 64},
                   {**base, 'writerProcessCreation100ns': 123},
                   {**base, 'writerProcessCreation100ns': '0'},
                   {**base, 'writerProcessCreation100ns': '1' * 21},
                   {**base, 'owner': {'future': True}},
                   {**base, 'ownedSdReturnCandidate': False},
                   {**base, 'unknown': float('nan')},
                   self.row('input-host-quarantine-cleared', pid=None)]
        for boundary in invalid:
            with self.subTest(boundary=boundary):
                self.assertEqual(self.repeats([base, boundary, base]), {})
        self.assertEqual(self.repeats([self.row(owner='future'), self.row(owner='future')]), {})

    def test_quarantine_explicit_lane_markers(self):
        birth = '134401550065218552'
        base = self.row(writerProcessCreation100ns=birth)
        held = self.row('input-host-quarantine-restore-held', writerProcessCreation100ns=birth)
        marked = lambda row, flag: {**row, 'quarantineRepeatSample': flag}
        wire = lambda rows: b''.join(json.dumps(row).encode() + b'\r\n' for row in rows)
        low, detail = 'native-lifecycle.log.1', 'native-detail.1.log'
        low_error = wire([marked(base, True)])
        detail_error = wire([marked(held, False)])
        with tempfile.TemporaryDirectory() as folder:
            path = Path(folder) / 'fixture.zip'
            with zipfile.ZipFile(path, 'w') as z:
                z.writestr('YeManCC-export-manifest.txt', f'processId=37\nwriterProcessCreation100ns={birth}\n')
                z.writestr(low, wire([base, marked(base, False), marked(base, False), base, marked(base, 1)]) + low_error)
                z.writestr(detail, wire([marked(held, True), marked(held, 0), held]) + b'bad-json\n' + detail_error)
                z.writestr('nested/' + detail, detail_error)
                z.writestr('native-detail.log.pending', detail_error)
                z.writestr('native-lifecycle.log.pending', low_error)
            result = audit_zip(path, {'baseEvents': [], 'baseEventCount': 0})
        self.assertEqual({(v['kind'], v['file'], tuple(v['exampleLines'])) for v in result['violations']},
                         {('quarantine-repeat-in-native-low', low, (6,)),
                          ('quarantine-resident-in-native-detail', detail, (5,))})
        for finding in result['violations']:
            is_low = finding['file'] == low
            field = 'nativeLowFindingWriterFootprint' if is_low else 'nativeDetailFindingWriterFootprint'
            self.assertEqual(sum(item['bytes'] for item in finding[field]['buckets'].values()),
                             len(low_error if is_low else detail_error))
        self.assertEqual(self.repeats([base, marked(base, False), base]), {})
        self.assertEqual(self.repeats([base, marked(base, 1), base]), {})

    def test_quarantine_zip_lane_and_duplicate_references_keep_raw_values(self):
        import warnings
        base = self.row()
        held = self.row('input-host-quarantine-restore-held', reason='pending')
        rows = [base, base, held, held, self.row('input-host-quarantine-cleared'), base]
        payload = ''.join(json.dumps(row) + '\n' for row in rows)
        with tempfile.TemporaryDirectory(prefix='ymcc-quarantine-audit-') as folder:
            path = Path(folder) / 'fixture.zip'
            with warnings.catch_warnings():
                warnings.simplefilter('ignore', UserWarning)
                with zipfile.ZipFile(path, 'w') as archive:
                    archive.writestr('YeManCC-export-manifest.txt', 'processId=37\n')
                    archive.writestr('native-lifecycle.log', payload)
                    archive.writestr('native-lifecycle.log', payload)
                    archive.writestr('native-lifecycle-detail.log', payload)
                    archive.writestr('native-lifecycle.log.1', json.dumps(base) + '\n')
                    archive.writestr('native-lifecycle.1.log', payload)
                    archive.writestr('native-lifecycle.1.log', json.dumps(base) + '\n')
                    archive.writestr('native-lifecycle.previous.log', payload)
                    archive.writestr('native-lifecycle.prev.log', json.dumps(base) + '\n{broken}\n' + json.dumps(base) + '\n')
                    archive.writestr('steam/native-lifecycle.1.log', payload)
                    archive.writestr('native-lifecycle.log.pending', payload)
            report = audit_zip(path, {'baseEvents': [], 'baseEventCount': 0})
            findings = report['violations']
            self.assertEqual(sorted((f['file'], f['archiveEntryOccurrence'], f['event'], f['exampleLines'])
                                    for f in findings), sorted(
                (name, occurrence, row['event'], [line])
                for name, occurrence in (('native-lifecycle.log', 0), ('native-lifecycle.log', 1),
                                         ('native-lifecycle.1.log', 0), ('native-lifecycle.previous.log', 0))
                for row, line in ((base, 2), (held, 4))))
            for finding in findings:
                self.assertEqual(finding['counts']['all'], 1)
                self.assertEqual(finding['counts']['currentPidMatch'], 1)
                self.assertFalse(finding['businessActionDuplicationInferred'])
                self.assertFalse(finding['processLifetimeProven'])
                self.assertFalse(finding['producerEmissionCoverageProven'])
            occurrences = [f['archiveEntryOccurrence'] for f in findings]
            self.assertEqual(len(set(occurrences)), 2)
            with zipfile.ZipFile(path) as archive:
                self.assertEqual(archive.read('native-lifecycle.log').decode(), payload)


from log_lane_audit import menu_composition_evidence


class MenuCompositionTests(unittest.TestCase):
    @staticmethod
    def composition(**values):
        return {'schema': 1, 'scope': 'same-key-per-browser-composition', 'diagnosticOnly': False,
            'nativeRequestSubmitted': True, 'inputCapabilityGranted': False, 'physicalInputProven': False,
            'status': 'per-browser-composition-uncertain', 'sourceTupleMatchesSelected': False,
            'browserMountedDuringKey': False, 'originalQueueLength': 2, 'selectedQueueLength': 2,
            'cachedComposition': {'scope': 'original-js-composition-cache', 'diagnosticOnly': True,
                'snapshot': 'before-supplement', 'atomic': False, 'maxQueueLength': 16,
                'mode': 2, 'windowID': 9007199254740991, 'queue': [-2147483648, 769]}, **values}

    @staticmethod
    def row(value, **fields):
        return {'event': 'screen-standalone-special', 'pid': 37, 'writerProcessCreation100ns': '123',
            'menuTarget': {'composition': value, 'identity': {'hostPid': 900, 'gamePid': 901}}, **fields}

    @classmethod
    def evidence(cls, values, current_pid='37'):
        return menu_composition_evidence([('native-lifecycle.log',
            [(i, cls.row(value)) for i, value in enumerate(values, 1)], {'archiveEntryOccurrence': 1})], current_pid)

    def test_attempt_true_with_uncertain_or_ended_owner_never_becomes_ack(self):
        statuses = ['per-browser-composition-submitted', 'per-browser-composition-uncertain',
                    'composition-owner-ended-after-submit', 'composition-observation-unavailable']
        report = self.evidence([self.composition(status=status) for status in statuses])
        self.assertEqual([row['reported']['status'] for row in report['observations']], statuses)
        for row in report['observations']:
            self.assertIs(row['reported']['nativeRequestSubmitted'], True)
            self.assertEqual(row['nativeCompletion'], 'UNKNOWN')
            self.assertEqual(row['physicalDelivery'], 'UNKNOWN')
            self.assertEqual(row['resourceReturn'], 'UNKNOWN')
        self.assertFalse(report['nativeCompletionInferred'])
        self.assertFalse(report['physicalDeliveryInferred'])
        self.assertFalse(report['capabilityGrantedByReader'])

    def test_signed_queue_order_null_empty_and_missing_remain_distinct(self):
        values = []
        for queue in ([-2147483648, 4294967295, 769], [769, 4294967295, -2147483648], None, []):
            value = self.composition()
            value['cachedComposition']['queue'] = queue
            value['cachedComposition']['mode'] = None
            value['cachedComposition']['windowID'] = None
            values.append(value)
        missing = self.composition();del missing['cachedComposition'];del missing['nativeRequestSubmitted']
        values.append(missing)
        before = json.dumps(values, sort_keys=True)
        report = self.evidence(values)
        projected = [row['reported'] for row in report['observations']]
        self.assertEqual([value['cachedComposition']['queue'] for value in projected[:4]],
                         [[-2147483648, 4294967295, 769], [769, 4294967295, -2147483648], None, []])
        self.assertNotIn('cachedComposition', projected[4])
        self.assertNotIn('nativeRequestSubmitted', projected[4])
        self.assertEqual(report['observations'][4]['submissionFlagState'], 'not-recorded')
        self.assertEqual(json.dumps(values, sort_keys=True), before)
        projected[0]['cachedComposition']['queue'].reverse()
        self.assertEqual(json.dumps(values, sort_keys=True), before)

    def test_writer_identity_uses_same_native_row_not_target_or_manifest(self):
        value = self.composition()
        rows = [self.row(value), self.row(value, pid=1 << 32), self.row(value, pid=None),
                self.row(value, writerProcessCreation100ns='0'), self.row(value, pid=38)]
        report = menu_composition_evidence([('native-detail.log.2', list(enumerate(rows, 1)), {})], '00037')
        result = report['observations']
        self.assertEqual(result[0]['writerPid'], '37')
        self.assertEqual(result[0]['writerProcessCreation100ns'], '123')
        self.assertTrue(result[0]['currentPidMatch'])
        self.assertIsNone(result[1]['writerPid']);self.assertIsNone(result[2]['writerPid'])
        self.assertIsNone(result[1]['currentPidMatch'])
        self.assertIsNone(result[3]['writerProcessCreation100ns'])
        self.assertFalse(result[3]['writerInstanceReported'])
        self.assertFalse(result[4]['currentPidMatch'])
        self.assertTrue(all(not row['writerLifetimeVerifiedByReader'] for row in result))

    def test_invalid_contract_types_and_future_fields_do_not_certify_proof(self):
        values = [self.composition(schema=True), self.composition(schema=2),
                  self.composition(diagnosticOnly=True), self.composition(physicalInputProven=True)]
        for field, value in [('queue', [1] * 17), ('queue', [0]), ('queue', [True]),
                             ('queue', [1.0]), ('mode', True), ('windowID', float('nan')), ('atomic', True)]:
            data = self.composition();data['cachedComposition'][field] = value;values.append(data)
        future = self.composition(futureDiagnostic={'queue': [9] * 1000})
        values.append(future)
        before = json.dumps(values, sort_keys=True)
        report = self.evidence(values)
        result = report['observations']
        self.assertTrue(all(row['compositionState'] == 'unrecognized' for row in result[:3]))
        self.assertIs(result[3]['reported']['physicalInputProven'], True)
        self.assertTrue(result[3]['fieldIssues'])
        for row in result[4:8]:
            self.assertNotIn('queue', row['reported']['cachedComposition'])
            self.assertTrue(row['fieldIssues'])
        self.assertEqual(result[-1]['fieldsNotProjected']['composition'], 1)
        self.assertNotIn('futureDiagnostic', result[-1]['reported'])
        self.assertFalse(report['typeCoverage']['retainedSupportedDescriptorCoverageComplete'])
        self.assertFalse(report['physicalDeliveryInferred'])
        self.assertEqual(json.dumps(values, sort_keys=True), before)

    def test_middle_only_cache_and_submission_types_survive_50000_rows(self):
        ordinary = self.composition()
        middle = self.composition();middle['cachedComposition']['queue'] = [4294967295, -2147483648, 769]
        skipped = self.composition(nativeRequestSubmitted=False, status='composition-owner-changed-before-submit')
        values = [ordinary] * 50000;values[25000] = middle;values[40000] = skipped
        report = self.evidence(values)
        self.assertEqual(report['compositionSlotsObserved'], 50000)
        self.assertEqual(report['typeCoverage']['retainedTypes'], 3)
        self.assertTrue(report['typeCoverage']['retainedSupportedDescriptorCoverageComplete'])
        self.assertLessEqual(len(report['observations']), 128)
        found = {row['line']: row for row in report['observations']}
        self.assertIn(25001, found);self.assertIn(40001, found)
        self.assertIn('first-type', found[25001]['selectionReasons'])
        self.assertEqual(found[25001]['reported']['cachedComposition']['queue'], [4294967295, -2147483648, 769])
        self.assertEqual(sum(item['matchingRows'] for item in report['descriptorTypes']), 50000)
        self.assertFalse(report['typeCoverage']['untrackedRowsAreUniqueTypes'])

    def test_descriptor_overflow_counts_rows_not_unseen_unique_types(self):
        values = []
        for window_id in range(70):
            value = self.composition();value['cachedComposition']['windowID'] = window_id
            values += [value, value]
        report = self.evidence(values)
        self.assertEqual(report['typeCoverage']['retainedTypes'], 64)
        self.assertEqual(report['typeCoverage']['untrackedRows'], 12)
        self.assertFalse(report['typeCoverage']['retainedSupportedDescriptorCoverageComplete'])
        self.assertFalse(report['typeCoverage']['untrackedRowsAreUniqueTypes'])
        self.assertLessEqual(len(report['observations']), 128)

    def test_zip_scope_and_duplicate_occurrences_keep_raw_values(self):
        import warnings
        value = self.composition();value['cachedComposition']['queue'] = [-2147483648, 4294967295, 769]
        row = self.row(value)
        with tempfile.TemporaryDirectory(prefix='ymcc-composition-reader-') as folder:
            path = Path(folder) / 'fixture.zip'
            payload = json.dumps(row) + '\n'
            with warnings.catch_warnings():
                warnings.simplefilter('ignore', UserWarning)
                with zipfile.ZipFile(path, 'w') as archive:
                    archive.writestr('YeManCC-export-manifest.txt', 'processId=37\n')
                    archive.writestr('native-lifecycle.log', payload)
                    archive.writestr('native-lifecycle.log', payload)
                    archive.writestr('native-detail.log.1', payload)
                    archive.writestr('native-lifecycle.log.1', json.dumps(self.row(None)) + '\n')
                    archive.writestr('steam/logs/native-lifecycle.log', payload)
                    archive.writestr('native-lifecycle.log.2', json.dumps({**row, 'event': 'unrelated'}) + '\n')
            before = hashlib.sha256(path.read_bytes()).hexdigest()
            result = audit_zip(path, {'baseEvents': [], 'baseEventCount': 0})
            report = result['commonEvidence']['menuCompositionEvidence']
            self.assertEqual(report['compositionSlotsObserved'], 4)
            self.assertEqual(report['explicitNullObservations'], 1)
            duplicate = [item for item in report['observations'] if item['file'] == 'native-lifecycle.log']
            self.assertEqual(len(duplicate), 2)
            self.assertNotEqual(duplicate[0]['archiveEntryOccurrence'], duplicate[1]['archiveEntryOccurrence'])
            for item in report['observations'][:3]:
                self.assertEqual(item['reported']['cachedComposition']['queue'], [-2147483648, 4294967295, 769])
            self.assertEqual(hashlib.sha256(path.read_bytes()).hexdigest(), before)

    def test_legacy_missing_and_explicit_null_do_not_imply_rejection(self):
        rows = [self.row(None), {'event': 'screen-standalone-special', 'pid': 37, 'menuTarget': {}},
                {'event': 'shortcut-frontend-button', 'pid': 37, 'menuTarget': 'invalid'},
                {'event': 'screen-standalone-special', 'pid': 37}]
        report = menu_composition_evidence([('native-lifecycle.log', list(enumerate(rows, 1)), {})], None)
        self.assertEqual(report['menuReceiptsObserved'], 4)
        self.assertEqual(report['menuReceiptsWithoutComposition'], 3)
        self.assertEqual(report['compositionSlotsObserved'], 1)
        self.assertEqual(report['explicitNullObservations'], 1)
        self.assertIsNone(report['observations'][0]['reported'])
        self.assertIsNone(report['observations'][0]['currentPidMatch'])
        self.assertEqual(report['observations'][0]['nativeCompletion'], 'UNKNOWN')
        empty = self.evidence([])
        self.assertIsNone(empty['typeCoverage']['retainedSupportedDescriptorCoverageComplete'])


class MenuInputTraceTests(unittest.TestCase):
    def test_native_route_nonobject_call_marks_parent_invalid_without_losing_valid_calls(self):
        for invalid in (None,False,True,1,1.0,'not-object',[],[{'future':True}]):
            with self.subTest(invalid=invalid):
                route=self.native_route([self.route_call(),invalid,self.route_call(ordinal=3)])
                raw=json.dumps(route,sort_keys=True)
                value=native_menu_route_evidence(route)
                self.assertEqual(value['state'],'invalid-fields')
                self.assertIn('calls[1]:invalid-observation',value['fieldIssues'])
                self.assertEqual(value['calls'][1]['fieldIssues'],['call:invalid-type'])
                self.assertEqual(value['calls'][0]['reported'],route['calls'][0])
                self.assertEqual(value['calls'][2]['reported'],route['calls'][2])
                self.assertEqual(value['reported']['eventCount'],3)
                self.assertEqual(value['callsNotListed'],0)
                self.assertEqual(value['reported']['callerCallback'],'UNKNOWN')
                self.assertEqual(value['reported']['nativeInputAcceptance'],'UNKNOWN')
                self.assertFalse(value['physicalDeliveryInferred'] or value['nativeInputAcceptanceInferred'])
                self.assertEqual(json.dumps(route,sort_keys=True),raw)

    def test_native_route_nonobject_call_remains_invalid_in_current_previous_zip_receipts(self):
        bad=self.trace(900);bad['nativeRoute']=self.native_route([None])
        good=self.trace(901);good['nativeRoute']=self.native_route([self.route_call(pid=901)])
        rows=[{'event':'screen-standalone-special','pid':37,'writerProcessCreation100ns':'123',
            'menuTarget':{'inputTrace':bad,'previousInputTrace':dict(bad,history=True,current=False)}},
            {'event':'screen-standalone-special','pid':37,'writerProcessCreation100ns':'123',
            'menuTarget':{'inputTrace':good}}]
        payload=''.join(json.dumps(row)+'\n' for row in rows)
        with tempfile.TemporaryDirectory() as root:
            archive=Path(root)/'route-child-invalid.zip'
            with zipfile.ZipFile(archive,'w') as z:
                z.writestr('YeManCC-export-manifest.txt','processId=37\n')
                z.writestr('native-lifecycle.log',payload)
                z.writestr('native-detail.log.1',json.dumps(rows[0])+'\n')
            raw=archive.read_bytes();report=audit_zip(archive,{'baseEvents':[]})
            snapshots=report['commonEvidence']['menuInputTraceEvidence']['snapshots']
            self.assertEqual([item['reported']['nativeRoute']['state'] for item in snapshots],
                ['invalid-fields','invalid-fields','reported-original-call-observations','invalid-fields','invalid-fields'])
            self.assertTrue(all(item['writerPid']=='37' and item['writerProcessCreation100ns']=='123' for item in snapshots))
            self.assertTrue(snapshots[1]['reported']['history']);self.assertFalse(snapshots[1]['reported']['current'])
            values=[q['value'] for q in iter_ai_records(archive) if q['record']=='json_record']
            self.assertEqual(values,rows+[rows[0]])
            self.assertEqual(archive.read_bytes(),raw)

    def test_trace_selection_late_native_route_and_active_tail_survive_rotations(self):
        current=self.trace(900);previous=dict(self.trace(901),history=True,current=False)
        rows=[(i,{'event':'screen-standalone-special','pid':37,'writerProcessCreation100ns':'123',
            'menuTarget':{'inputTrace':current,'previousInputTrace':previous}}) for i in range(1,301)]
        observed=dict(current,nativeRoute=self.native_route([self.route_call(pid=900)]))
        rows[159]=(160,{**rows[159][1],'menuTarget':{'inputTrace':observed,'previousInputTrace':previous}})
        rare=dict(previous,nativeRoute=self.native_route([self.route_call(pid=901,outcome='threw',resultKind='throw')],
            status='stopped',reason='window-expired',observedWindowMs=10000))
        rows[209]=(210,{**rows[209][1],'menuTarget':{'inputTrace':current,'previousInputTrace':rare}})
        report=menu_input_trace_evidence([('native-lifecycle.log',rows,{'archiveEntryOccurrence':0}),
            ('native-lifecycle.log.1',[(i,{**row,'pid':38}) for i,row in rows],{'archiveEntryOccurrence':0})],'37')
        refs={(q['file'],q['line'],q['slot']) for q in report['snapshots']}
        for ref in (('native-lifecycle.log',160,'inputTrace'),('native-lifecycle.log',210,'previousInputTrace'),
            ('native-lifecycle.log',300,'inputTrace'),('native-lifecycle.log',300,'previousInputTrace'),
            ('native-lifecycle.log.1',300,'previousInputTrace')):
            self.assertIn(ref,refs)
        selected=next(q for q in report['snapshots'] if (q['file'],q['line'],q['slot'])==
            ('native-lifecycle.log',210,'previousInputTrace'))
        self.assertEqual(selected['reported']['nativeRoute']['calls'][0]['reported']['outcome'],'threw')
        self.assertEqual(selected['reported']['identity']['hostPid'],901)
        self.assertEqual(selected['writerPid'],'37');self.assertEqual(selected['writerProcessCreation100ns'],'123')
        self.assertEqual(len(report['snapshots']),128)
        self.assertEqual(report['traceSnapshotsObserved'],1200)
        self.assertEqual(report['traceSnapshotsNotListed'],1072)

    def test_trace_selection_fixed_witness_space_and_user_reasons_are_bounded(self):
        base=self.trace()
        def carrier(trace,slot='inputTrace'):
            return {'event':'screen-standalone-special','pid':37,'menuTarget':{slot:trace}}
        rows=[(i,carrier(base)) for i in range(1,2001)]
        shapes=[None,base,dict(base,nativeRoute=None),dict(base,nativeRoute=True),dict(base,nativeRoute={}),
            dict(base,nativeRoute=self.native_route([],attempted=False,status='not-started',observedWindowMs=None)),
            dict(base,nativeRoute=self.native_route([])),
            dict(base,nativeRoute=self.native_route([],status='stopped')),
            dict(base,nativeRoute=self.native_route([],status='future-status'))]
        calls=[None,[self.route_call()]*17,[],
            [self.route_call(outcome='threw',resultKind='throw')],[self.route_call()]]
        for slot in ('inputTrace','previousInputTrace'):
            for trace in shapes:
                rows.append((len(rows)+1,carrier(trace,slot)))
            for value in calls:
                route=self.native_route([]);route['calls']=value
                rows.append((len(rows)+1,carrier(dict(base,nativeRoute=route),slot)))
        for i in range(2000):
            rows.append((len(rows)+1,carrier(dict(base,nativeRoute=self.native_route([],reason='foreign-reason-'+str(i))))))
        secondary=[(1,{'event':'screen-standalone-special','pid':37,
            'menuTarget':{'inputTrace':base,'previousInputTrace':base}})]
        report=menu_input_trace_evidence([('native-lifecycle.log',rows,{}),('native-detail.log',secondary,{})],'37')
        selection=report['snapshotSelection']
        self.assertEqual(selection['maxFixedWitnesses'],32)
        self.assertEqual(selection['firstShapeWitnesses'],28)
        self.assertEqual(selection['activeNameTailWitnesses'],4)
        self.assertEqual(len(report['snapshots']),128)
        self.assertEqual(report['traceSnapshotsObserved'],len(rows)+2)
        self.assertEqual(report['traceSnapshotsNotListed'],len(rows)+2-128)
        self.assertLess(len(json.dumps(report)),600000)
        self.assertFalse(selection['crossFileTimeOrderInferred'] or selection['duplicateNameWinnerSelected'])

