    def test_monitor_lane_snapshot_in_low_stream_is_reported_without_relabeling_controls(self):
        snapshot = {'event':'monitor-data-snapshot','pid':37,'snapshot':{'seq':1}}
        low_control = {'event':'monitor-lifecycle','pid':37,'reason':'started'}
