        with tempfile.TemporaryDirectory() as root:
            path=Path(root)/'directory.zip'
            with zipfile.ZipFile(path,'w') as archive:
                archive.writestr('folder/',b'retained-directory-bytes')
                archive.writestr('native-lifecycle.log','{"pid":37,"event":"after-directory"}\n')
            self.corrupt_member(path,0)
            report=audit_zip(path,{'baseEvents':[]})
            self.assertEqual(report['crcFirstBadEntry'],'folder/')
