        from log_lane_audit import copy_staged_boundary_evidence as view
        for status in ('staged-read-error','staged-size-error','staged-inspection-error'):
            result=view({'status':status});self.assertEqual(result['inspectionFailure']['state'],'missing')
            self.assertEqual(result['state'],'reported-inspection-error');self.assertIsNone(result['inspectionFailure']['reportedKind'])
