    def test_adaptive_deadline_suppression_keeps_the_prior_query_separate(self):
        from log_lane_audit import windows_export_query_record
        for streak,cooldown in ((1,60000),(2,120000),(3,240000)):
            row=self.reused();previous=row['windowsSleepDiagnostics']['recentDeadline']
            previous.update(deadlineStreak=streak,streakWindowMs=300000,cooldownMs=cooldown,
                            ageMs=cooldown-1,retryAfterMs=1)
