    def test_missing_birth_and_invalid_identity_are_distinct_from_null_birth(self):
        v=self.availability();v['touchHapticSummaryPreparationEvidence'].pop('writerProcessCreation100ns');self.assertEqual(self.read(v)['state'],'invalid-fields')
        v=self.availability();v['touchHapticSummaryPreparationEvidence']['writerProcessCreation100ns']=None;self.assertEqual(self.read(v)['state'],'reported-source-observations')
        v=self.availability();v['touchHapticSummaryPreparationEvidence']['writerPid']=True;self.assertEqual(self.read(v)['state'],'invalid-fields')
