class HapticFailureAttemptTests(unittest.TestCase):
    @staticmethod
    def row(attempted=0,notAttempted=0,unknown=0,failed=None):
        return {'event':'gamepad-touch-haptics-summary','pid':37,'writerProcessCreation100ns':'134392901619393799',
            'sent':3,'failed':attempted+notAttempted+unknown if failed is None else failed,'dropped':2,
            'reasons':{'source-pending':1},'errors':{},'failureAttemptEvidence':{
                'schema':1,'scope':'unsuccessful-receipts-original-output-attempt-flag;excludes-dropped',
                'attempted':attempted,'notAttempted':notAttempted,'unknown':unknown,
                'outputApiFailureProven':False,'physicalFailureProven':False}}

    def test_no_attempt_attempt_unknown_and_mixed_are_distinct(self):
        from log_lane_audit import haptic_failure_attempt_record as read
        samples=[(self.row(),'reported-no-unsuccessful'),(self.row(notAttempted=1),'reported-not-attempted-only'),
            (self.row(attempted=1),'reported-attempted-only'),(self.row(unknown=1),'reported-unknown-only'),
            (self.row(attempted=1,notAttempted=1,unknown=1),'reported-mixed-attempt-states')]
        for row,state in samples:
            before=json.dumps(row);view=read(row);self.assertEqual(view['state'],state)
            self.assertFalse(view['physicalFailureInferred'] or view['outputApiFailureInferred'] or view['droppedAddedToFailed'])
            self.assertEqual(json.dumps(row),before)

    def test_legacy_missing_null_and_wrong_schema_do_not_infer_attempt_from_reason(self):
        from log_lane_audit import haptic_failure_attempt_record as read
        row=self.row(notAttempted=1);del row['failureAttemptEvidence']
        self.assertEqual(read(row)['state'],'missing');self.assertNotIn('notAttempted',read(row)['reported'])
        for value,state in ((None,'null'),([], 'invalid-fields'),({'schema':2},'unsupported'),({'schema':True},'unsupported')):
            self.assertEqual(read({**row,'failureAttemptEvidence':value})['state'],state)

    def test_strict_counter_types_equation_and_proof_flags(self):
        from log_lane_audit import haptic_failure_attempt_record as read
        for field in ('attempted','notAttempted','unknown'):
            for bad in (True,-1,1.0,'1',1<<64):
                row=self.row(notAttempted=1);row['failureAttemptEvidence'][field]=bad
                self.assertEqual(read(row)['state'],'invalid-fields')
        for field in ('sent','failed','dropped'):
            row=self.row();row[field]=False;self.assertEqual(read(row)['state'],'invalid-fields')
        row=self.row(attempted=1,failed=0);self.assertEqual(read(row)['state'],'invalid-fields')
        for key in ('physicalFailureProven','outputApiFailureProven'):
            row=self.row();row['failureAttemptEvidence'][key]=True;self.assertEqual(read(row)['state'],'invalid-fields')
        row=self.row(unknown=(1<<53)+1);self.assertEqual(read(row)['reported']['unknown'],(1<<53)+1)

    def test_last_error_code_is_preserved_without_becoming_an_error_count(self):
        from log_lane_audit import haptic_failure_attempt_record as read
        row=self.row(attempted=3);row['errors']={'write-failed':1167};row['reasons']={'write-failed':3}
        view=read(row);self.assertEqual(view['lastErrorCodes'],{'write-failed':1167})
        self.assertEqual(view['reasonCounts'],{'write-failed':3})
        row['errors']['future-'+'x'*100000]=123
        view=read(row);self.assertEqual(view['errorsUnprojectedEntries'],1);self.assertEqual(view['lastErrorCodes'],{'write-failed':1167})

    def test_rare_middle_unsuccessful_type_survives_50000_success_summaries(self):
        from log_lane_audit import haptic_failure_attempt_evidence as read
        rows=[(i+1,self.row()) for i in range(50000)]
        rows[25000]=(25001,self.row(notAttempted=1));rows[26000]=(26001,self.row(attempted=1));rows[27000]=(27001,self.row(unknown=1))
        view=read([('native-lifecycle.log',rows,{'archiveEntryOccurrence':0})],37)
        self.assertEqual(view['rowsObserved'],50000)
        self.assertEqual(view['countsByState'],{'reported-no-unsuccessful':49997,'reported-not-attempted-only':1,'reported-attempted-only':1,'reported-unknown-only':1})
        self.assertTrue({25001,26001,27001}<={q['line'] for q in view['rows']})
        self.assertLessEqual(len(view['rows']),41);self.assertEqual(view['rowsNotListed'],50000-len(view['rows']))

    def test_exact_native_carrier_event_scope_and_zip_dispatch(self):
        from log_lane_audit import haptic_failure_attempt_evidence as read
        row=self.row(notAttempted=1)
        view=read([('native-lifecycle.log',[(1,row),(2,{**row,'event':'other'})],{}),
            ('frontend-trace.log',[(1,row)],{}),('native-detail.log.1',[(1,row)],{'archiveEntryOccurrence':2})],37)
        self.assertEqual(view['rowsObserved'],2);self.assertEqual(view['rows'][1]['archiveEntryOccurrence'],2)
        with tempfile.TemporaryDirectory() as directory:
            path=Path(directory)/'logs.zip'
            with zipfile.ZipFile(path,'w') as archive:archive.writestr('native-lifecycle.log',json.dumps(row)+'\n')
            view=audit_zip(path,{'baseEvents':[],'baseEventCount':0})['commonEvidence']['touchHapticFailureAttemptEvidence']
            self.assertEqual(view['countsByState'],{'reported-not-attempted-only':1})


class SensorRetirementRecoveryScopeTests(unittest.TestCase):
    scope='screen-and-sensor-retirement-memo-rearm-after-original-good-event-append;file-exit-or-named-preparation-fault'
    @classmethod
    def receipt(cls):
        value=AuditTests.native_screen_preparation_receipt()
        value['stats']['eventAppendRecovery'].update(scope=cls.scope,unrecoveredPreparationFailureObserved=False,unrecoveredSensorRetirementPreparationFailureObserved=True)
        return value
    @staticmethod
    def view(value):return native_append_failure_evidence({'nativeLogFailureEvidence':value},{'status':'selected'},'37')['eventAppendRecovery']
    def test_exact_sensor_scope_keeps_three_causes_separate(self):
        value=self.receipt();original=json.dumps(value,sort_keys=True);view=self.view(value)
        self.assertEqual(view['state'],'reported');self.assertEqual(view['reportedScope'],self.scope)
        self.assertEqual(view['sensorRetirementPreparationFailureState'],'reported')
        self.assertIs(view['reported']['unrecoveredSensorRetirementPreparationFailureObserved'],True)
        self.assertIs(view['reported']['unrecoveredFailureObserved'],False);self.assertIs(view['reported']['unrecoveredPreparationFailureObserved'],False)
        self.assertFalse(view['sensorRetirementPreparationFailureProvesFileFailure'] or view['sensorRetirementReofferActuallyWrittenInferred'] or view['businessOrDeviceRecoveryInferred'])
        self.assertEqual(json.dumps(value,sort_keys=True),original)
    def test_legacy_scopes_never_fill_sensor_false(self):
        for value in (AuditTests.native_screen_recovery_receipt(),AuditTests.native_screen_preparation_receipt()):
            view=self.view(value);self.assertEqual(view['state'],'reported');self.assertEqual(view['sensorRetirementPreparationFailureState'],'not-described-by-scope')
            self.assertNotIn('unrecoveredSensorRetirementPreparationFailureObserved',view['reported'])
    def test_sensor_missing_and_mistyped_flags_remain_unknown(self):
        for invalid in (None,0,1,'false',[],{}):
            value=self.receipt();value['stats']['eventAppendRecovery']['unrecoveredSensorRetirementPreparationFailureObserved']=invalid
