class JsonlDecodeQualityMemoryTests(unittest.TestCase):
    def test_valid_replacement_characters_are_counted_without_rejecting_json(self):
        value={'text':'a\ufffd中\ufffd'};raw=b'\xef\xbb\xbf'+(json.dumps(value,ensure_ascii=False)+'\r\n').encode()
        rows,quality=load_rows(raw);self.assertEqual(rows,[(1,value)]);self.assertEqual(quality['utf8ReplacementCharacters'],2);self.assertEqual(quality['invalidRows'],[])
    def test_invalid_bytes_keep_exact_quality_count_and_no_replacement_evidence(self):
        raw=b'{"text":"\xff\xc0\xaf\xef\xbf\xbd"}\n{"good":true}\n'
        rows,quality=load_rows(raw);self.assertEqual(rows,[(2,{'good':True})]);self.assertEqual(quality['utf8ReplacementCharacters'],raw.decode('utf-8-sig',errors='replace').count('\ufffd'))
        self.assertEqual(quality['invalidRows'][0]['kind'],'invalid-utf8-row');self.assertFalse(quality['tailBoundary']['copyCutProven'])
    def test_multibyte_fragments_across_lf_do_not_join_into_characters(self):
        for text in ('中','😀','\ufffd','\ufeff'):
            encoded=text.encode()
            for split in range(1,len(encoded)):
                raw=encoded[:split]+b'\n'+encoded[split:]+b'\n{}\n';rows,quality=load_rows(raw)
                self.assertEqual(quality['utf8ReplacementCharacters'],raw.decode('utf-8-sig',errors='replace').count('\ufffd'))
                self.assertEqual(rows[-1],(3,{}));self.assertEqual(quality['lineCount'],3)
    def test_later_bom_and_unicode_separators_remain_original_payload(self):
        value={'text':'\ufeffa\u2028b\u2029c\ufffd'};raw=b'{}\n'+json.dumps(value,ensure_ascii=False).encode()
        rows,quality=load_rows(raw);self.assertEqual(rows,[(1,{}),(2,value)]);self.assertEqual(quality['lineCount'],2)
        self.assertEqual(quality['utf8ReplacementCharacters'],1);self.assertEqual(quality['tailBoundary']['state'],'unterminated');self.assertEqual(quality['invalidRows'],[])
    def test_all_single_byte_quality_counts_and_bom_prefixes_match_decoder(self):
        for raw in [bytes([v]) for v in range(256)]+[b'',b'\xef',b'\xef\xbb',b'\xef\xbb\xbf',b'\xef\xbb\xbf\n',b'\xef\xbb\xbf\xff\n']:
            _,quality=load_rows(raw);self.assertEqual(quality['utf8ReplacementCharacters'],raw.decode('utf-8-sig',errors='replace').count('\ufffd'))


class JsonlPhysicalLineViewTests(unittest.TestCase):
    def test_replay_view_keeps_exact_lf_line_count_empty_crlf_and_tail(self):
        from log_lane_audit import _PhysicalLfLines
        for data in (b'',b'\n',b'\n\n',b'a',b'a\n',b'a\r\nb\n',b'\xef\xbb\xbf{}\n\xff',b'{}\n\n{}'):
            expected=data.split(b'\n')
            if expected and expected[-1]==b'':expected.pop()
            view=_PhysicalLfLines(data)
            actual=[r[:-1] if r.endswith(b'\n') else r for r in view]
            self.assertEqual(actual,expected);self.assertEqual(len(view),len(expected));self.assertEqual(list(view),list(view))
            self.assertIs(view.data,data)
    def test_invalid_witness_hashes_and_excerpts_exclude_lf_but_keep_cr(self):
        data=b'{}\r\n'+b'{broken}\r\n'+b'\xff'*300+b'\n{"partial":'
        _,quality=load_rows(data);evidence=quality['invalidLineByteEvidence'];parts=data.split(b'\n')
        for row in evidence['observations']:
            raw=parts[row['line']-1];self.assertEqual(row['rawLineSha256'],hashlib.sha256(raw).hexdigest());self.assertEqual(row['byteLength'],len(raw))
            self.assertEqual(bytes.fromhex(row['prefix']['hex']),raw[:128])
            at=row['suffix']['relativeByteOffset'];self.assertEqual(bytes.fromhex(row['suffix']['hex']),raw[at:])
            self.assertEqual(row['byteOffset'],sum(len(r)+1 for r in parts[:row['line']-1]))
        self.assertFalse(quality['tailBoundary']['copyCutProven'] or quality['tailBoundary']['sourceDamageProven'])
    def test_legacy_list_byte_witness_input_remains_identical_to_view(self):
        from log_lane_audit import _PhysicalLfLines,invalid_line_byte_evidence
        data=b'\xff\r\n{broken}\n{"partial":';_,quality=load_rows(data)
        items=data.split(b'\n');old=invalid_line_byte_evidence(items,quality['invalidRows'],False)
        current=invalid_line_byte_evidence(_PhysicalLfLines(data),quality['invalidRows'],False)
        self.assertEqual(old,current);self.assertEqual(current,quality['invalidLineByteEvidence'])


class SnapshotAttemptContextTests(unittest.TestCase):
    @staticmethod
    def context(**fields):
        return {'schema':1,'scope':'ordinary-export-staging-attempt;diagnostic-only','attempt':1,'maxAttempts':2,
            'exportOperation':AuditTests.export_operation_sample(),**fields}
    @staticmethod
    def view(document):
        from log_lane_audit import archive_attempt_context_record
        return archive_attempt_context_record(document)
    def test_known_context_preserves_exact_operation_and_attempt_without_proof(self):
        value=self.context(attempt=2);value['exportOperation']['writerProcessCreation100ns']='9007199254740993';before=json.dumps(value,sort_keys=True)
        view=self.view({'archiveAttemptContext':value});self.assertEqual(view['state'],'reported-staging-attempt');self.assertEqual(view['reported']['attempt'],2)
        self.assertEqual(view['exportOperation']['reported']['writerProcessCreation100ns'],'9007199254740993')
        self.assertFalse(view['operationRowsJoined'] or view['archiveMemberContentBound'] or view['currentExportOutcomeProven'] or view['writerLifetimeVerified'])
        self.assertEqual(json.dumps(value,sort_keys=True),before)
    def test_missing_null_bad_types_and_future_scope_remain_unknown(self):
        for document,state in (({},'missing'),({'archiveAttemptContext':None},'null'),({'archiveAttemptContext':False},'invalid-type')):self.assertEqual(self.view(document)['state'],state)
        for fields in ({'schema':True},{'schema':2},{'scope':'future'}):self.assertNotEqual(self.view({'archiveAttemptContext':self.context(**fields)})['state'],'reported-staging-attempt')
    def test_attempt_and_operation_conflicts_are_rejected(self):
        for fields in ({'attempt':True},{'attempt':0},{'attempt':3},{'maxAttempts':3},{'exportOperation':None}):self.assertEqual(self.view({'archiveAttemptContext':self.context(**fields)})['state'],'invalid-fields')
        value=self.context();value['exportOperation']['id']='37-42-4';self.assertEqual(self.view({'archiveAttemptContext':value})['exportOperation']['state'],'contradictory')
    def test_old_unknown_birth_is_not_supplied_from_neighbor_or_manifest(self):
        value=self.context();value['exportOperation']['writerProcessCreation100ns']=None
        view=self.view({'archiveAttemptContext':value,'writerProcessCreation100ns':'123'});self.assertEqual(view['state'],'reported-staging-attempt')
        self.assertEqual(view['exportOperation']['state'],'reported-pid-operation;birth-unknown');self.assertIsNone(view['exportOperation']['reported']['writerProcessCreation100ns'])
    def test_copy_sources_keep_native_context_separate_and_rows_unchanged(self):
        from log_lane_audit import copy_observation_evidence
        row=AuditTests.copy_observation_row();selections={n:{'status':'selected','selectedOccurrence':0} for n in ('log-export-snapshot.json','steam/steam-log-export.json')}
        docs={'log-export-snapshot.json':{'files':[row],'archiveAttemptContext':self.context()},'steam/steam-log-export.json':{'files':[]}}
        view=copy_observation_evidence(docs,selections);self.assertEqual(view['sources'][0]['archiveAttemptContext']['state'],'reported-staging-attempt')
        self.assertNotIn('archiveAttemptContext',view['sources'][1]);self.assertFalse(view['archiveEntryMatchInferred'])
    def test_unknown_payload_is_bounded_and_duplicate_receipts_supply_no_context(self):
        value=self.context(private='secret'*50000);view=self.view({'archiveAttemptContext':value});self.assertEqual(view['unprojectedFieldCount'],1)
        self.assertNotIn('secret',json.dumps(view));self.assertLess(len(json.dumps(view)),4000)
        with tempfile.TemporaryDirectory() as root:
            p=Path(root)/'duplicate-context.zip';text=json.dumps({'archiveAttemptContext':self.context(),'files':[]})
            with zipfile.ZipFile(p,'w') as z:z.writestr('log-export-snapshot.json',text);z.writestr('log-export-snapshot.json',text)
            report=audit_zip(p,{'baseEvents':[]});source=report['commonEvidence']['copyObservationEvidence']['sources'][0]
            self.assertNotEqual(source['selectionStatus'],'selected');self.assertNotIn('archiveAttemptContext',source)


