class NativeControlWindowReaderTests(unittest.TestCase):
    @staticmethod
    def sample():
        return json.loads((Path(__file__).resolve().parent/'fixtures/log_native_control_window.json').read_bytes())
    @staticmethod
    def record(row):
        from log_lane_audit import native_control_window_record
        return native_control_window_record(row)
    @staticmethod
    def evidence(rows,metadata=None,filename='native-detail.log'):
        from log_lane_audit import native_control_window_evidence
        return native_control_window_evidence([(filename,list(enumerate(rows,1)),metadata or {})],'37')
    @staticmethod
    def ranges(view):
        return {v['field']:v for v in view['fieldRangesAcrossRetainedReportedWindows']}
    @staticmethod
    def retired(row):
        value=json.loads(json.dumps(row['allObservedControls']))
        for key in ('snapshotKnown','drained','pendingTailAtExport','retiredBindingWindows','diagnosticContentionSinceProcessStart','overwrittenRetiredBindingWindows','lostRetiredBindingObservations'):value.pop(key,None)
        return value
    def test_actual_fixture_projects_all26_fields_without_changing_input(self):
        row=self.sample();before=json.dumps(row,sort_keys=True);value=self.record(row)
        self.assertEqual(value['state'],'reported-projection');self.assertEqual(value['current']['state'],'reported-window')
        self.assertEqual(len(value['current']['ranges']['fields']),26);self.assertEqual(value['current']['reported']['observations'],1)
        self.assertEqual(value['current']['reported']['hostAcks'],1);self.assertEqual(json.dumps(row,sort_keys=True),before)
    def test_native_signal_scope_marker_preserves_projection_and_requires_exact_contract(self):
        row=self.sample()
        row['event']='input-native-signal-window'
        expected=self.record(row)
        row.pop('counterScope')
        row['nativeSignalScopeSchema']=1
        self.assertEqual(self.record(row),expected)
        for changes in ({'nativeSignalScopeSchema':True},{'nativeSignalScopeSchema':2},
                        {'event':'another-event'},{'counterScope':None},{'counterScope':'unknown'}):
            with self.subTest(changes=changes):
                view=self.record({**row,**changes})
                self.assertIn('counterScope:unsupported',view['samplerCounters']['fieldIssues'])
        self.assertEqual(self.record({**row,'formatVersion':2})['state'],'unsupported-format')

    def test_unknown_flags_ignore_zero_and_stale_ranges(self):
        row=self.sample();window=row['allObservedControls'];window['fieldValueKnown']=[False]*26;window['minimum']=[999]*26;window['maximum']=[-999]*26
        view=self.evidence([row]);fields=self.ranges(view)
        self.assertEqual(fields['lt']['unknownValueWindows'],1);self.assertIsNone(fields['lt']['minimum']);self.assertIsNone(fields['lt']['maximum'])
        self.assertNotIn('minimum',self.record(row)['current']['ranges']['fields'][0]);self.assertFalse(view['completeControlHistoryProven'])
    def test_genuine_known_zero_is_distinct_from_unknown(self):
        row=self.sample();fields=self.ranges(self.evidence([row]));self.assertEqual(fields['rawLtByte']['reportedRangeWindows'],1)
        self.assertEqual((fields['rawLtByte']['minimum'],fields['rawLtByte']['maximum']),(0,0));self.assertEqual(fields['rawLtByte']['unknownValueWindows'],0)
    def test_field_order_and_array_shape_are_not_guessed(self):
        for change in ('order','minimum','maximum','fieldValueKnown'):
            row=self.sample();value=row['allObservedControls']
            if change=='order':value['fieldOrder'][0],value['fieldOrder'][1]=value['fieldOrder'][1],value['fieldOrder'][0]
            else:value[change].pop()
            record=self.record(row);self.assertEqual(record['current']['ranges']['fields'],[])
            fields=self.ranges(self.evidence([row]));self.assertIsNone(fields['rawLtByte']['minimum']);self.assertEqual(fields['rawLtByte']['windowsWithoutFieldProjection'],1)
    def test_nonfinite_huge_boolean_and_reversed_known_ranges_are_invalid(self):
        for invalid in (float('inf'),float('nan'),True,None,10**500):
            row=self.sample();row['allObservedControls']['minimum'][0]=invalid;value=self.record(row)
            self.assertEqual(value['current']['ranges']['fields'][0]['state'],'invalid-reported-range');json.dumps(value,allow_nan=False)
        row=self.sample();row['allObservedControls']['minimum'][0]=1
        self.assertEqual(self.record(row)['current']['ranges']['fields'][0]['state'],'invalid-reported-range')
    def test_missing_invalid_counters_are_not_zero(self):
        for invalid in (None,True,-1,'0',1<<64):
            row=self.sample();row['allObservedControls']['nonfiniteValues']=invalid;value=self.record(row)
            self.assertNotIn('nonfiniteValues',value['current']['reported']);self.assertGreater(value['current']['fieldIssueCount'],0)
        row=self.sample();row['allObservedControls'].pop('hostAcks');self.assertNotIn('hostAcks',self.record(row)['current']['reported'])
    def test_counter_conflicts_are_reported_without_comparing_other_windows(self):
        row=self.sample();row['allObservedControls']['hostAcks']=2
        self.assertIn('hostAcks:exceeds-submitAttempts',self.record(row)['current']['fieldIssues'])
        row=self.sample();row['window'].update(observations=1000,attempts=1000,accepted=1000,semanticNeutral=1000,semanticNeutralAccepted=1000,selectedSourceKnownReads=1000,selectedSourceLiveReads=1000,repeatedKnownSourceReads=999)
        value=self.record(row);self.assertEqual(value['state'],'reported-projection');self.assertEqual(value['current']['reported']['observations'],1)
        self.assertEqual(value['samplerCounters']['reported']['observations'],1000);self.assertFalse(value['differentWindowCountsCompared'])
    def test_contention_and_missing_containers_do_not_supply_ranges(self):
        row=self.sample();row['allObservedControls']={'snapshotKnown':False,'reason':'contended'};value=self.record(row)
        self.assertEqual(value['current']['state'],'reported-contended');view=self.evidence([row]);self.assertEqual(view['fieldRangesAcrossRetainedReportedWindows'],[])
        for data,state in ((None,'null'),(False,'invalid-type')):
            row=self.sample();row['allObservedControls']=data;self.assertEqual(self.record(row)['current']['state'],state)
        row=self.sample();row.pop('allObservedControls');self.assertEqual(self.record(row)['current']['state'],'missing')
    def test_future_root_or_window_schema_and_scope_stay_unsupported(self):
        for version in (True,None,2):
            row=self.sample();row['formatVersion']=version;self.assertEqual(self.record(row)['state'],'unsupported-format')
        for key,bad,state in (('schemaVersion',True,'unsupported-schema'),('schemaVersion',2,'unsupported-schema'),('scope','future','unsupported-scope')):
            row=self.sample();row['allObservedControls'][key]=bad;self.assertEqual(self.record(row)['current']['state'],state)
    def test_source_zero_observations_ignore_stored_default_trigger_ranges(self):
        row=self.sample();source=row['allObservedControls']['selectedSource'];source.update(observations=0,liveObservations=0,bothRawTriggers127Frames=0,triggerMin=[255,255],triggerMax=[0,0])
        value=self.record(row);self.assertEqual(value['current']['selectedSource']['triggerRanges']['state'],'not-observed;stored-defaults-ignored')
        view=self.evidence([row]);self.assertEqual(view['reportedZeroSourceObservationWindows'],1);self.assertFalse(view['sourceDamageOrPhysicalLossProven'])
    def test_retired_window_ranges_are_labeled_without_joining_bindings(self):
        row=self.sample();retired=self.retired(row);retired['runId']='other-binding';retired['minimum'][0]=50;retired['maximum'][0]=60;row['allObservedControls']['retiredBindingWindows']=[retired]
        value=self.record(row);self.assertEqual(value['retired'][0]['state'],'reported-window');self.assertEqual(value['retiredWindowsReportedCount'],1)
        view=self.evidence([row]);field=self.ranges(view)['rawLtByte'];self.assertEqual((field['minimum'],field['maximum'],field['reportedRangeWindows']),(0,60,2))
        self.assertFalse(view['differentWindowsOrRequestsJoined'] or view['samplerAndControlCountersSummed'])
    def test_retired_overflow_and_nested_private_payload_are_bounded(self):
        row=self.sample();retired=self.retired(row);retired['private']='secret'*100000;retired['retiredBindingWindows']=[retired.copy()]
        row['allObservedControls']['retiredBindingWindows']=[retired]*5000
        value=self.record(row);self.assertEqual(len(value['retired']),2);self.assertEqual(value['retiredRowsNotInspected'],4998)
        self.assertEqual(value['retiredWindowCountState'],'over-capacity');self.assertNotIn('secret',json.dumps(value));self.assertLess(len(json.dumps(value)),40000)
    def test_control_edges_overflow_keeps_first_and_last8_only(self):
        row=self.sample();window=row['allObservedControls'];edge=window['controlEdges'][0];window.update(observations=17,controlEdgeTransitions=17,overwrittenOldestControlEdges=0)
        window['controlEdges']=[edge]*17;value=self.record(row)['current']['controlEdges']
        self.assertEqual(value['observedRows'],17);self.assertEqual(len(value['observations']),16);self.assertEqual(value['rowsNotInspected'],1)
        self.assertEqual([v['index'] for v in value['observations']],list(range(8))+list(range(9,17)))
    def test_edge_overwrite_and_nonfinite_reports_remain_diagnostic(self):
        row=self.sample();window=row['allObservedControls'];edge=window['controlEdges'][0];window.update(observations=20,controlEdgeTransitions=20,overwrittenOldestControlEdges=4,nonfiniteValues=5)
        window['controlEdges']=[edge]*16;value=self.record(row);self.assertEqual(value['current']['state'],'reported-window')
        view=self.evidence([row]);self.assertFalse(view['sourceDamageOrPhysicalLossProven'] or view['completeControlHistoryProven'])
    def test_field_issue_details_and_edge_payloads_are_bounded(self):
        row=self.sample();window=row['allObservedControls'];window['controlEdges']=[{}]*16;window['privatePayload']='secret'*100000
        value=self.record(row);self.assertEqual(len(value['current']['fieldIssues']),32);self.assertGreater(value['current']['fieldIssueCount'],32)
        self.assertNotIn('secret',json.dumps(value));self.assertLess(len(json.dumps(value)),30000)
    def test_sampler_counter_scope_and_subset_conflicts_remain_explicit(self):
        row=self.sample();row['window']['accepted']=2;self.assertIn('accepted:exceeds-attempts',self.record(row)['samplerCounters']['fieldIssues'])
        row=self.sample();row['counterScope']='future';self.assertIn('counterScope:unsupported',self.record(row)['samplerCounters']['fieldIssues'])
        row=self.sample();row['window']['observations']=False;self.assertNotIn('observations',self.record(row)['samplerCounters']['reported'])
    def test_middle_loss_unknown_and_contention_witnesses_survive_large_input(self):
        good=self.sample();rows=[good]*5000
        unknown=self.sample();unknown['allObservedControls']['fieldValueKnown'][0]=False;rows[999]=unknown
        loss=self.sample();loss['allObservedControls']['lostRetiredBindingObservations']=1;rows[1999]=loss
        contended=self.sample();contended['allObservedControls']={'snapshotKnown':False,'reason':'contended'};rows[2999]=contended
        missing=self.sample();missing.pop('window');rows[3999]=missing
        view=self.evidence(rows);lines={v['line'] for v in view['observations']}
        self.assertTrue({1000,2000,3000,4000}.issubset(lines));self.assertLessEqual(len(view['observations']),34)
        self.assertEqual(view['rowsNotListed'],5000-len(view['observations']));self.assertEqual(view['rowsObserved'],5000)
    def test_duplicate_rotations_and_single_pass_members_count_rows_only(self):
        from log_lane_audit import native_control_window_evidence
        row=self.sample();members=((name,iter([(1,row)]),{'archiveEntryOccurrence':index}) for index,name in enumerate(('native-detail.log','native-detail.log.1')))
        view=native_control_window_evidence(members,'37');self.assertEqual(view['rowsObserved'],2)
        self.assertEqual(self.ranges(view)['rawLtByte']['reportedRangeWindows'],2);self.assertFalse(view['queryOrUniqueApiCallsCounted'])
        self.assertEqual([v['archiveEntryOccurrence'] for v in view['observations']],[0,1])
    def test_writer_birth_and_metadata_do_not_become_lifetime_authority(self):
        row=self.sample();view=self.evidence([row],{'archiveEntryOccurrence':1,'containerOnly':True,'private':'secret'})
        item=view['observations'][0];self.assertEqual(item['writerProcessCreation100ns'],'9007199254740993');self.assertFalse(item['writerLifetimeProven'])
        self.assertNotIn('secret',json.dumps(view));row.pop('writerProcessCreation100ns');self.assertIsNone(self.evidence([row])['observations'][0]['writerProcessCreation100ns'])
    def test_unrecognized_carriers_and_no_events_do_not_expand_range_tables(self):
        view=self.evidence([self.sample()],filename='steam/native-detail.log');self.assertEqual(view['rowsObserved'],0)
        self.assertEqual(view['fieldRangesAcrossRetainedReportedWindows'],[]);self.assertEqual(view['fieldRangeProjectionState'],'not-observed-or-uninterpretable')
    def test_drain_and_pending_tail_are_separate_from_complete_history(self):
        row=self.sample();row['allObservedControls'].update(drained=False,pendingTailAtExport=True)
        self.assertEqual(self.record(row)['current']['state'],'reported-window')
        row['allObservedControls']['drained']=True;self.assertIn('pendingTailAtExport:contradictory-drain-flag',self.record(row)['current']['fieldIssues'])
    def test_current_audit_exposes_control_evidence_without_replacing_other_views(self):
        with tempfile.TemporaryDirectory() as directory:
            path=Path(directory)/'control.zip'
            with zipfile.ZipFile(path,'w') as archive:archive.writestr('native-detail.log',json.dumps(self.sample())+'\n')
            view=audit_zip(path,{'baseEvents':[]})['commonEvidence'];self.assertEqual(view['nativeControlWindowEvidence']['rowsObserved'],1)
            self.assertIn('nativeForegroundHelperEvidence',view)


class InputHostSubmitStatsEvidenceTests(unittest.TestCase):
    def test_same_row_request_and_stats_keep_different_sequence_scopes(self):
        from log_lane_audit import input_host_submit_stats_record
        detail = dict(ok=True, runId='run', epoch=2, persona='steamdeck', frameOk=21, frameFail=1,
                      neutralOk=2, neutralFail=0, lastSequence=39, lastDetail='report-submitted')
        request = dict(schema=1, requestId='request', sequence=40, persona='steamdeck', protocolPowerGeneration=11)
        row = dict(ok=True, runId='run', hostInstanceId='host', epoch=2, persona='elite', phase='wake-recover',
                   queryPowerGeneration=10, queryCompletedPowerGeneration=12,
                   submitStatsReceipt=request, detail=json.dumps(detail))
        record = input_host_submit_stats_record(row)
        self.assertEqual(record['state'], 'reported-bound-accepted-request')
        self.assertEqual(record['acceptedRequest']['sequence'], 40)
        self.assertEqual(record['hostStats']['lastSequence'], 39)
        self.assertTrue(record['nativePowerChangedDuringQuery'])
        self.assertEqual(record['nativeScope']['persona'], 'elite')
        for change, expected in ((dict(submitStatsReceipt=None, persona='steamdeck'), 'accepted-request-identity-unavailable'),
                                 (dict(ok=False, submitStatsReceipt=None), 'query-failed'),
                                 (dict(ok=False), 'contradictory-failed-query'),
                                 (dict(submitStatsReceipt={**request, 'sequence':True}), 'invalid-accepted-request'),
                                 (dict(detail=json.dumps({**detail, 'runId':'different'})), 'same-row-scope-unresolved'),
                                 (dict(detail='{"ok":true,'+json.dumps(detail)[1:]), 'invalid-or-missing-host-stats')):
            self.assertEqual(input_host_submit_stats_record({**row, **change})['state'], expected)
        legacy = {k:v for k,v in row.items() if k!='submitStatsReceipt'}
        self.assertEqual(input_host_submit_stats_record({**legacy,'persona':'steamdeck'})['state'], 'legacy-identity-unavailable')

    def test_archive_reports_only_ordered_resident_rows_with_original_locations(self):
        import warnings

        rows = [dict(event='input-host-submit-stats', ok=False, phase='release-window-close'),
                dict(event='unrelated'), dict(event='input-host-submit-stats', ok=True, detail='{}')]
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / 'stats.zip'
            with zipfile.ZipFile(path, 'w') as archive:
                archive.writestr('native-lifecycle.log.1', ''.join(json.dumps(row)+'\n' for row in rows))
                with warnings.catch_warnings():
                    warnings.simplefilter('ignore', UserWarning)
                    archive.writestr('native-lifecycle.log.1', json.dumps(rows[0])+'\n')
                archive.writestr('native-lifecycle.1.log', '\n'+json.dumps(rows[0])+'\n')
                archive.writestr('native-lifecycle.previous.log', json.dumps(rows[0])+'\n')
