    def test_5000_counter_shapes_count_rows_without_deleting_or_joining_frames(self):
        row=self.sample();v=self.evidence([row]*5000);g=v['coarseCounterGroups'];self.assertEqual(v['rowsObserved'],5000);self.assertEqual(len(g['groups']),1);self.assertEqual(g['groups'][0]['rows'],5000)
        self.assertFalse(g['fullRowEqualityProven'] or g['deduplicationAuthorized'] or g['rawRowsRemoved']);self.assertEqual(v['rowsNotListed'],5000-len(v['observations']))
