        v=native_control_window_evidence([('native-detail.log',[(1,a),(2,b),(3,c)],{}),('native-detail.log.1',[(1,a)],{})],37)
        self.assertEqual(len(v['coarseCounterGroups']['groups']),4);self.assertEqual([q['rows'] for q in v['coarseCounterGroups']['groups']],[1,1,1,1])
