        name='native-detail.log.'+'1'*1000;g=self.evidence([self.sample()],name)['coarseCounterGroups'];self.assertEqual(len(g['groups']),1);s=g['groups'][0]['signature'];self.assertIsNone(s['file']);self.assertEqual(len(s['fileNameSha256']),64);self.assertNotIn(name,json.dumps(g))
