        v=self.evidence([a,b]);self.assertEqual(len(v['coarseCounterGroups']['groups']),1);self.assertFalse(v['coarseCounterGroups']['fullRowEqualityProven']);self.assertEqual(next(q for q in v['fieldRangesAcrossRetainedReportedWindows'] if q['field']=='rawLtByte')['maximum'],99)
