    def test_marginals_cover_every_row_after_joint_shape_capacity(self):
        rows=[]
        for i in range(50):
            row=self.sample();row['allObservedControls']['runId']='r'+str(i);row['allObservedControls']['observations']=100+i;rows.append(row)
        value=self.evidence(rows);self.assertIn('counterMarginals',value);m=value['counterMarginals'];self.assertEqual(m['rowsObserved'],50)
