        field=next(q for q in relation['fields'] if q['scope']=='control' and q['field']=='observations')
        self.assertEqual((field['reportedValueRows'],field['minimum'],field['maximum']),(50,100,149));self.assertFalse(m['counterValuesSummed'] or m['uniqueFramesCounted'] or m['crossCounterCorrelationProven'])
