class IpcRecoveryReofferReaderTests(unittest.TestCase):
    @staticmethod
    def row(reason='type-recovery-witness',epoch=1):
        row=AuditTests.ipc_row(reason=reason);row['failureLogSelection'].update(schema=2,scope='current-Native-process-type-witness-and-reoffer;not-operation-or-delivery-proof',recoveryEpoch=epoch,
            typeIndex=0 if reason in ('first-type','repeat-type','type-recovery-witness') else None);return row
    @staticmethod
    def summary(rows):return AuditTests.ipc_summary(rows)
    def test_all_schema2_reasons_keep_type_index_and_lane_roles(self):
        reasons=('first-type','repeat-type','capacity-first-witness','capacity-detail','unclassified-first-witness','unclassified-detail','type-recovery-witness','capacity-recovery-witness','unclassified-recovery-witness')
        result=self.summary([self.row(r) for r in reasons]);self.assertEqual(result['rowCountsBySelection'],dict.fromkeys(reasons,1));self.assertEqual(result['reportedDetailSelectionInLowRows'],3)
        self.assertFalse(result['uniqueFailedCommandsCounted'] or result['rendererReceiptOrPhysicalResultProven'])
    def test_legacy_schema_does_not_receive_new_recovery_reasons_or_epoch(self):
        row=self.row();row['failureLogSelection'].update(schema=1,scope='current-Native-process-type-witness;not-operation-or-delivery-proof')
        result=self.summary([row]);self.assertEqual(result['rowCountsBySelection'],{'invalid-fields':1})
        self.assertEqual(self.summary([AuditTests.ipc_row()])['rowCountsBySelection'],{'first-type':1})
    def test_epoch_is_strict_uint64_and_zero_recovery_is_contradictory(self):
        result=self.summary([self.row(epoch=v) for v in (False,-1,1<<64,0,(1<<64)-1)])
        self.assertEqual(result['rowCountsBySelection'],{'invalid-fields':3,'contradictory':1,'type-recovery-witness':1})
        self.assertEqual(result['observations'][-1]['failure']['selection']['reported']['recoveryEpoch'],(1<<64)-1)
        self.assertFalse(result['observations'][-1]['failure']['selection']['recoveryReofferProvesDelivery'])
    def test_scope_shape_and_type_index_are_not_permissive(self):
        rows=[]
        for key,bad in (('scope','future'),('schema',3),('typeIndex',None),('extra',True)):
            row=self.row();row['failureLogSelection'][key]=bad;rows.append(row)
        self.assertEqual(self.summary(rows)['rowCountsBySelection'],{'invalid-fields':1,'unsupported':1,'contradictory':1,'unsupported-shape':1})
    def test_new_lane_audit_flags_only_supported_repeat_markers(self):
        rows=[self.row(r) for r in ('type-recovery-witness','repeat-type','capacity-recovery-witness','capacity-detail','unclassified-recovery-witness','unclassified-detail')]
        bad=self.row('repeat-type');bad['failureLogSelection']['recoveryEpoch']=False;rows.append(bad)
        with tempfile.TemporaryDirectory(prefix='ymcc-ipc-reoffer-') as root:
            path=Path(root)/'fixture.zip'
            with zipfile.ZipFile(path,'w') as z:
                z.writestr('native-lifecycle.log','\n'.join(map(json.dumps,rows))+'\n')
            result=audit_zip(path,{'baseEvents':[]})
        violations=[v for v in result['violations'] if v['kind']=='ipc-repeated-or-untracked-detail-in-native-low']
        self.assertEqual(len(violations),1);self.assertEqual(violations[0]['counts']['all'],3);self.assertEqual(violations[0]['exampleLines'],[2,4,6])

    def test_resident_ipc_witnesses_are_flagged_only_in_root_detail(self):
        import warnings

        events = ('ipc-response-delivery-failed', 'ipc-response-delivery-exception', 'ipc-response-serialization-failed')
        qualified = [dict(self.row(reason), event=event, pid=37, writerProcessCreation100ns='123')
                     for event in events
                     for reason in ('first-type', 'capacity-first-witness', 'unclassified-first-witness',
                                    'type-recovery-witness', 'capacity-recovery-witness', 'unclassified-recovery-witness')]
        qualified.append(dict(AuditTests.ipc_row(), pid=37, writerProcessCreation100ns='123'))
        detail = [self.row(reason) for reason in ('repeat-type', 'capacity-detail', 'unclassified-detail')]
        invalid = [self.row(epoch=0), dict(self.row(), event='unrelated'),
                   {k: v for k, v in self.row().items() if k != 'failureLogSelection'}]
        for key, bad in (('recoveryEpoch', False), ('scope', 'future'), ('schema', True), ('typeIndex', None), ('extra', True)):
            row = self.row()
            row['failureLogSelection'][key] = bad
            invalid.append(row)

        def wire(row):
            return (json.dumps(row) + '\r\n').encode('ascii')

        names = ('native-detail.log', 'native-detail.log.previous', 'native-detail.2.log', 'native-detail.2.log')
        payload = b'{partial\r\n' + b''.join(map(wire, (*qualified, *detail, *invalid)))
        with tempfile.TemporaryDirectory(prefix='ymcc-ipc-witness-lanes-') as root:
            path = Path(root) / 'ipc-witnesses.zip'
            with warnings.catch_warnings():
                warnings.simplefilter('ignore', UserWarning)
                with zipfile.ZipFile(path, 'w') as z:
                    for name in (*names, 'nested/native-detail.log'):
                        z.writestr(name, payload)
                    z.writestr('native-lifecycle.log', b''.join(map(wire, qualified)))
            result = audit_zip(path, {'baseEvents': list(events)})
        findings = [(v['file'], v['archiveEntryOccurrence'], v['event'], v['exampleLines'], v['counts']['all'],
                     sum(part['bytes'] for part in v['nativeDetailFindingWriterFootprint']['buckets'].values()))
                    for v in result['violations'] if v['kind'] == 'ipc-failure-witness-in-native-detail']
        expected = []
        for idx, name in enumerate(names):
            for event in events:
                selected = [(line, row) for line, row in enumerate(qualified, 2) if row['event'] == event]
                expected.append((name, int(idx == 3), event, [line for line, _ in selected],
                                 len(selected), sum(len(wire(row)) for _, row in selected)))
        self.assertCountEqual(findings, expected)

    def test_middle_rare_recovery_witness_survives_original_summary_bound(self):
        rows=[self.row('repeat-type') for _ in range(5000)];rows[2500]=self.row('type-recovery-witness',27)
        result=self.summary(rows);self.assertLessEqual(len(result['observations']),result['maxListedObservations']);self.assertIn(2501,[r['line'] for r in result['observations']])
        self.assertEqual(result['rowCountsBySelection'],{'repeat-type':4999,'type-recovery-witness':1})
    def test_recovery_marker_does_not_supply_message_health_or_writer_birth(self):
        row={'event':'ipc-response-delivery-failed','pid':37,'failureLogSelection':self.row()['failureLogSelection']}
        result=self.summary([row]);observation=result['observations'][0]
        self.assertEqual(observation['failure']['message']['state'],'missing');self.assertEqual(observation['writerBirthState'],'missing');self.assertFalse(observation['writerLifetimeProven'])
        self.assertFalse(result['frequencyRateComputed'] or result['sourceCurrentOrLoadedInferred'])


