class CompactQualityErrorViewTests(unittest.TestCase):
    @staticmethod
    def module():
        import log_lane_audit
        return log_lane_audit
    def test_dense_invalid_details_are_bounded_with_full_counts_and_byte_witnesses(self):
        raw=b'bad\n'*10000+b'broken-tail';rows,quality=load_rows(raw,compact_quality=True);_,legacy=load_rows(raw)
        self.assertEqual(rows,[]);self.assertLessEqual(len(quality['invalidRows']),24)
        self.assertEqual(quality['errorDetailRetention']['invalidRowsObserved'],10001)
        self.assertEqual(quality['invalidLineByteEvidence'],legacy['invalidLineByteEvidence'])
        self.assertEqual(list(self.module()._quality_unknown_lines(quality)),list(range(1,10002)))
        self.assertLessEqual(quality['errorDetailRetention']['uninterpretedRangeBytes'],16)
    def test_non_object_details_are_bounded_without_turning_omissions_into_blanks(self):
        raw=b'null\n'*10000;rows,quality=load_rows(raw,compact_quality=True)
        self.assertEqual(rows,[]);self.assertEqual(quality['invalidRows'],[]);self.assertLessEqual(len(quality['nonObjectLines']),16)
        self.assertEqual(self.module()._quality_error_counts(quality),(0,10000))
        self.assertEqual(quality['nonObjectLines'][:8],list(range(1,9)));self.assertEqual(quality['nonObjectLines'][-8:],list(range(9993,10001)))
    def test_unlisted_middle_bad_line_still_resets_exact_continuity(self):
        value={'event':'rog.hid-discovery-summary','pid':7,'fixture':True};line=json.dumps(value).encode()+b'\n'
        raw=b'bad\n'*2500+line+b'bad\n'+line+b'bad\n'*1000+line;rows,quality=load_rows(raw,compact_quality=True)
        self.assertNotIn(2502,[q['line'] for q in quality['invalidRows']])
        actual=list(self.module().continuity_rows(rows,self.module()._quality_unknown_lines(quality)))
        self.assertEqual([q[2] for q in actual],[True,True,True])
        self.assertEqual(self.module().duplicate_snapshots(rows,unknown_lines=self.module()._quality_unknown_lines(quality)),[])
        sampled=list(self.module().continuity_rows(rows,[q['line'] for q in quality['invalidRows']]))
        self.assertFalse(sampled[1][2])
    def test_serialized_samples_cannot_substitute_for_missing_complete_boundary_index(self):
        raw=b'bad\n'*100+b'{}\n';rows,quality=load_rows(raw,compact_quality=True);saved=json.loads(json.dumps(quality))
        self.assertIsNone(self.module()._quality_unknown_lines(saved))
        self.assertTrue(all(q[2] for q in self.module().continuity_rows(rows,None)))
        _,small=load_rows(b'bad\n{}\n',compact_quality=True);self.assertEqual(self.module()._quality_unknown_lines(json.loads(json.dumps(small))),(1,))
    def test_fixed_rejection_domains_keep_middle_rare_duplicate_key_and_counts(self):
        from unittest.mock import patch
        decode=json.loads
        def controlled_loads(data,*args,**kwargs):
            if data=='["fixture-decoder-refusal"]\n':raise RecursionError('fixture recursion refusal')
            return decode(data,*args,**kwargs)
        raw=(b'{"x":NaN}\n'*3000+b'{"fanOwnerState":1,"fanOwnerState":2}\n'+b'{"x":1e999}\n'+b'['*130+b'0'+b']'*130+
             b'\n["fixture-decoder-refusal"]\n'+b'{"x":NaN}\n'*3000)
        with patch('ai_log_reader.json.loads', side_effect=controlled_loads):
            _,quality=load_rows(raw,compact_quality=True)
        retained=quality['errorDetailRetention']
        self.assertEqual(retained['invalidEvidenceByReason'],{'non-standard-number':6000,'duplicate-key':1,'non-finite-number':1,'nesting-limit':2})
        self.assertEqual(retained['nestingLimitByBoundary'],{'container-depth-budget':1,'parser-recursion-capacity':1})
        self.assertEqual({q['jsonNestingEvidence']['boundary']:q['line'] for q in quality['invalidRows'] if 'jsonNestingEvidence' in q},
                         {'container-depth-budget':3003,'parser-recursion-capacity':3004})
        duplicate=next(q for q in quality['invalidRows'] if 'duplicateKeyEvidence' in q)
        self.assertEqual(duplicate['line'],3001);self.assertEqual(duplicate['duplicateKeyEvidence']['prefixHex'],b'fanOwnerState'.hex())
        self.assertLessEqual(len(quality['invalidRows']),24)
    def test_original_byte_coordinates_bom_crlf_utf8_and_nonobject_semantics_remain_exact(self):
        raw=b'\xef\xbb\xbf{"text":"ok"}\r\n'+b'bad\r\n'*100+b'\xff\n[1]\n'+b'{"x":1,"x":2}'
        rows,quality=load_rows(raw,compact_quality=True);old_rows,legacy=load_rows(raw)
        self.assertEqual(rows,old_rows);self.assertEqual(quality['invalidLineByteEvidence'],legacy['invalidLineByteEvidence'])
        for key in ('lineCount','validObjectRows','endsWithNewline','utf8ReplacementCharacters','jsonlDelimiter','tailBoundary','tailInterpretation'):self.assertEqual(quality[key],legacy[key])
        originals={q['line']:q for q in legacy['invalidRows']}
        for q in quality['invalidRows']:self.assertEqual(q,originals[q['line']])
    def test_process_envelope_uses_full_error_counts_instead_of_listed_sample_lengths(self):
        raw=b'{}\n'+b'bad\n'*1000+b'null\n'*500+b'{}\n';rows,quality=load_rows(raw,compact_quality=True)
        result=self.module().process_export_member_envelope('model-adaptation-session.jsonl',rows,{},quality,raw)
        self.assertEqual(result['quality']['invalidRowCount'],1000);self.assertEqual(result['quality']['nonObjectLineCount'],500);self.assertEqual(result['quality']['blankLineCount'],0)
        self.assertFalse(result['retainedRowsConsistencyVerified'])
    def test_valid_inputs_and_default_legacy_lists_keep_original_quality_shape(self):
        for raw in (b'',b'{}\n',b'\r\n{"text":"\xe7\x95\x8c"}',b'{}\n\n'):
            self.assertEqual(load_rows(raw,compact_quality=True),load_rows(raw))
        _,quality=load_rows(b'bad\n'*40+b'null\n'*40);self.assertEqual(len(quality['invalidRows']),40);self.assertEqual(len(quality['nonObjectLines']),40)
        self.assertNotIn('errorDetailRetention',quality)
    def test_range_index_replays_exact_big_gaps_and_refuses_invalid_order(self):
        index=self.module()._UnknownLineRanges();values=[1,2,3,127,128,129,16384,16385,1<<60]
        for value in values:index.append(value)
        index.finish();self.assertEqual(list(index),values);self.assertEqual(list(index),values);self.assertEqual((index[0],index[-1],len(index)),(1,1<<60,len(values)))
        self.assertIsInstance(index.encoded,bytes)
        with self.assertRaises(ValueError):index.append((1<<60)+1)
        other=self.module()._UnknownLineRanges();other.append(3)
        for value in (False,0,2,3):
            with self.assertRaises(ValueError):other.append(value)
    def test_all_small_adversarial_unknown_subsets_match_original_sorted_set_semantics(self):
        module=self.module();records=[(n,{}) for n in range(1,12)]
        for mask in range(256):
            values=[n+1 for n in range(8) if mask&(1<<n)];index=module._UnknownLineRanges()
            for value in values:index.append(value)
            index.finish();self.assertEqual(list(module.continuity_rows(records,index)),list(module.continuity_rows(records,values)))
    def test_report_does_not_claim_original_bytes_or_complete_source_copied_into_summary(self):
        raw=b'bad\n'*100;_,quality=load_rows(raw,compact_quality=True);value=quality['errorDetailRetention']
        self.assertFalse(value['originalInputBytesChanged'] or value['originalMemberBytesCopiedIntoReport'] or value['completeSourceCollectionProven'])
        self.assertFalse(value['serializedReportContainsEncodedBoundaryIndex'])
    def test_full_audit_default_uses_bounded_quality_and_preserves_duplicate_member_scopes(self):
        import warnings
        with tempfile.TemporaryDirectory(prefix='ymcc-compact-quality-') as root:
            path=Path(root)/'fixture.zip'
            with warnings.catch_warnings():
                warnings.simplefilter('ignore',UserWarning)
                with zipfile.ZipFile(path,'w') as archive:
                    archive.writestr('native-lifecycle.log',b'bad\n'*1000)
                    archive.writestr('native-lifecycle.log',b'null\n'*80)
            report=audit_zip(path,{'baseEvents':[]})
        files=[q for q in report['files'] if q['file']=='native-lifecycle.log']
        self.assertEqual([q['quality']['errorDetailRetention']['uninterpretedPhysicalLines'] for q in files],[1000,80])
        self.assertTrue(all(len(q['quality']['invalidRows'])<=24 and len(q['quality']['nonObjectLines'])<=16 for q in files))
        json.dumps(report)


