            self.assertIn('reported-recovery-failed',view['exportSnapshot']['record']['reportedSignals'])
            self.assertEqual(report['snapshotReceipt']['evidenceScope'],'original-export-snapshot');self.assertEqual(path.read_bytes(),before)
