class WebViewPostShowNudgeReaderTests(unittest.TestCase):
    @staticmethod
    def row(**changes):
        return {'event': 'post-show-nudge', 'writerEnvelopeSchema': 1, 'writerPid': 37,
                'writerProcessCreation100ns': '9007199254740993', **changes}

    def test_writer_and_mode_never_fall_back_to_pid_or_truthiness(self):
        from log_lane_audit import webview_post_show_nudge_evidence
        rows = [self.row(firstMainReveal=True), self.row(firstMainReveal=False), self.row(),
                self.row(firstMainReveal=None), self.row(firstMainReveal=1),
                self.row(firstMainReveal=True, writerProcessCreation100ns='9007199254740992'),
                self.row(firstMainReveal=False, writerPid=38),
                self.row(firstMainReveal=False, writerEnvelopeSchema=True, pid=37),
                self.row(firstMainReveal=False, writerProcessCreation100ns=None, browserProcessId=37)]
        members = [('webview-failures.log', list(enumerate(rows, 1)), {'archiveEntryOccurrence': 0})]
        view = webview_post_show_nudge_evidence(members, ('37', '9007199254740993'))
        self.assertEqual(view['rowCountsByWriterAndMode'], {
            'export-writer': {'first-main-reveal': 1, 'ordinary-refresh': 1, 'not-reported': 1,
                              'reported-null': 1, 'invalid-type': 1},
            'same-pid-other-birth': {'first-main-reveal': 1}, 'other-writer': {'ordinary-refresh': 1},
            'writer-unresolved': {'ordinary-refresh': 2}})
        unknown = webview_post_show_nudge_evidence(members, None)
        self.assertNotIn('export-writer', unknown['rowCountsByWriterAndMode'])
        self.assertEqual(unknown['rowCountsByWriterAndMode']['export-writer-unresolved']['ordinary-refresh'], 2)
        self.assertFalse(view['comResultOrVisiblePixelsOrInputRecoveryProven'])

    def test_zip_manifest_rotations_and_duplicate_occurrences(self):
        op = {'id': '37-12-1', 'schema': 1, 'ordinal': '1', 'startedTickMs': '12', 'writerPid': 37,
              'writerProcessCreation100ns': '9007199254740993',
              'scope': 'admitted-ordinary-log-export;diagnostic-correlation-only'}
        manifest = ('processId=37\nexportOperation=' + json.dumps(op) + '\n').encode()
        first = (json.dumps(self.row(firstMainReveal=True)) + '\n').encode()
        normal = (json.dumps(self.row(firstMainReveal=False, extra='private-path')) + '\n').encode()
        failure = b'{"event":"process-failed","kind":"browser"}\n'
        with tempfile.TemporaryDirectory() as root:
            path = Path(root) / 'nudge.zip'
            AuditTests.receipt_selection_write(path, [('YeManCC-export-manifest.txt', manifest),
                ('webview-failures.log', failure + first), ('webview-failures.log', b'\n' + normal),
                ('webview-failures.log.1', first), ('foreign/webview-failures.log', first),
                ('webview-failures.log.\uff11', first), ('native-lifecycle.log', first)])
            common = audit_zip(path, {'baseEvents': []})['commonEvidence']
            view = common['webviewPostShowNudgeEvidence']
            self.assertEqual(common['uiPresentationEvidence']['rowCountsByReportedSignal'], {'reported-process-failure': 1})
            self.assertEqual(view['rowsObserved'], 3)
            self.assertEqual(view['rowCountsByWriterAndMode'], {'export-writer': {'first-main-reveal': 2, 'ordinary-refresh': 1}})
            first, second = view['firstWitnessPerWriterRelationAndMode']
            self.assertEqual([(first['archiveEntryOccurrence'], first['line']),
                              (second['archiveEntryOccurrence'], second['line'])], [(0, 2), (1, 2)])
            self.assertNotIn('private-path', json.dumps(view))


class OverlayRendererProbeReaderTests(unittest.TestCase):
    def row(self, phase, **fields):
        return {'event':'game-overlay-surface','pid':89,'writerProcessCreation100ns':'9007199254740993',
                'phase':phase,'session':12,'requestedTick':300,'hresult':0,**fields}

    def reply(self, **fields):
        return self.row('renderer-replied', **{'replyTick':304,'parse':'parsed','currentSession':True,
            'renderer':{'readyState':'complete','visibility':'visible','hasFocus':False,'app':True,'body':True},**fields})

    def view(self, rows, filename='native-lifecycle.log.1'):
        from log_lane_audit import overlay_renderer_probe_evidence
        return overlay_renderer_probe_evidence([(filename,enumerate(rows,1),{'archiveEntryOccurrence':0})])

    def test_exact_key_survives_callback_before_request_log_and_keeps_focus_false(self):
        report=self.view([self.reply(),self.row('renderer-requested')]);example,=report['examples']
        self.assertEqual(report['keysByState'],{'paired-current-renderer-object':1})
        self.assertEqual(example['reply']['elapsedMs'],4)
        self.assertEqual(example['writerProcessCreation100ns'],'9007199254740993')
        self.assertIs(example['reply']['hasFocus'],False)
        self.assertFalse(report['dispatchOrScriptReplyProvesInputOrPixels'])

    def test_pid_birth_session_and_tick_all_needed(self):
        for fields in ({'pid':90},{'writerProcessCreation100ns':'9007199254740994'},{'session':13},{'requestedTick':301}):
            with self.subTest(fields=fields):
                self.assertEqual(self.view([self.row('renderer-requested'),self.reply(**fields)])['keysByState'],
                                 {'request-only':1,'reply-only':1})
        for fields in ({'pid':True},{'session':True},{'requestedTick':None},{'writerProcessCreation100ns':'09007199254740993'}):
            with self.subTest(fields=fields):
                view=self.view([self.row('renderer-requested'),self.reply(**fields)])
                self.assertEqual(view['rowsByReportedPhaseAndCoverage']['rowsWithoutCompleteKey'],1)
                self.assertEqual(view['keysByState'],{'request-only':1})

    def test_dispatch_failure_stale_malformed_and_oversize_are_distinct(self):
        cases=[(self.row('renderer-requested',hresult=-1),None,'dispatch-rejected'),
               (self.row('renderer-requested'),self.row('renderer-reply-invalid',replyTick=304),'paired-invalid-reply'),
               (self.row('renderer-requested'),self.reply(currentSession=False),'paired-no-longer-current'),
               (self.row('renderer-requested'),self.reply(hresult=-1),'paired-reply-error'),
               (self.row('renderer-requested'),self.reply(parse='oversize',renderer=None),'paired-payload-or-context-unavailable'),
               (self.row('renderer-requested'),self.reply(replyTick=299),'paired-payload-or-context-unavailable'),
               (self.row('renderer-requested',hresult=True),self.reply(),'paired-status-unavailable')]
        for request,reply,state in cases:
            with self.subTest(state=state):
                rows=[request] if reply is None else [request,reply]
                self.assertEqual(self.view(rows)['keysByState'],{state:1})

    def test_repeated_matching_copy_and_rejected_dispatch_with_reply_are_ambiguous(self):
        for rows in ([self.row('renderer-requested'),self.reply(),self.reply()],
                     [self.row('renderer-requested',hresult=-1),self.reply()]):
            self.assertEqual(self.view(rows)['keysByState'],{'ambiguous-or-conflicting':1})
        view=self.view([self.row('renderer-requested'),self.reply()], 'foreign/native-lifecycle.log')
        self.assertEqual(view['keysByState'],{})

    def test_legacy_invalid_reply_lacks_key_and_limits_never_hide_total(self):
        legacy=self.row('renderer-reply-invalid');del legacy['requestedTick']
        rows=[legacy]+[self.row('renderer-requested',requestedTick=i) for i in range(4200)]
        view=self.view(rows)
        self.assertEqual(view['rowsByReportedPhaseAndCoverage']['rowsWithoutCompleteKey'],1)
        self.assertEqual(view['rowsByReportedPhaseAndCoverage']['rowsBeyondKeyLimit'],104)
        self.assertEqual(view['keysByState'],{'request-only':4096});self.assertEqual(len(view['examples']),16)

    def test_real_zip_uses_both_native_carriers(self):
        with tempfile.TemporaryDirectory() as directory:
            archive=Path(directory)/'overlay.zip'
            with zipfile.ZipFile(archive,'w') as z:
                z.writestr('native-lifecycle.log',json.dumps(self.row('renderer-requested'))+'\n')
                z.writestr('native-detail.log.1',json.dumps(self.reply())+'\n')
            report=audit_zip(archive,{'baseEvents':[]})
        result=report['commonEvidence']['overlayRendererProbeEvidence']
        self.assertEqual(result['keysByState'],{'paired-current-renderer-object':1})
        self.assertEqual(result['examples'][0]['reply']['witness']['file'],'native-detail.log.1')


class LifecycleFiniteOutcomeReaderTests(unittest.TestCase):
    @staticmethod
    def rows():
        common={'pid':7012,'writerProcessCreation100ns':'134394066260992255'}
        values=[
            {'event':'gyro-power-early-pause-completed','source':'os-suspend-callback','subscriptionsStopped':False,'generation':9007199254740993,'physicalSleepVerified':False},
            {'event':'gyro-power-start-current','commandCompleted':True,'publicPowerCurrent':False,'suspendRequested':True,'powerGeneration':8,'producerPowerGeneration':7,'observedPowerGeneration':8,'notificationSequence':9007199254740995,'suspendSerial':3,'physicalSleepVerified':False},
            {'event':'fxsound-toggle','ok':False,'enabled':True,'copied':False,'reused':True,'repaired':False,'reason':'private-reason-path'},
            {'event':'settings-upgrade-repaired','status':'repaired','source':'defaults','archived':0,'automaticHardwareDeactivated':True},
            {'event':'gamepad-feedback-stop-pending','phase':'bounded-retry','ownershipRetained':True,'zeroApiAccepted':False,'hardwareStopObserved':False,'slot':1,'pulseGeneration':100,'identityEpisode':11,'retryInMs':100,'identityEpoch':7,'sourceGeneration':9,'sourcePowerGeneration':1,'legacyPathless':False,'reason':'identity-unresolved','writeError':None}]
        return [{**common,**row} for row in values]
    @staticmethod
    def view(row):
        import log_lane_audit as m
        return m.native_finite_outcome_record(row)
    def test_five_new_event_shapes_are_typed_without_health_claim(self):
        expected=['reported-subscriptions-retained','reported-start-command-completed','reported-toggle-refused','reported-settings-repaired','reported-stop-retry-pending']
        for row,disposition in zip(self.rows(),expected):
            value=self.view(row);self.assertIsNotNone(value);self.assertEqual(value['state'],'reported-fields');self.assertEqual(value['reportedDisposition'],disposition)
            self.assertFalse(value['currentBusinessSuccessInferred'] or value['physicalOrResourceReturnProven'])
    def test_missing_null_invalid_and_unsupported_remain_separate(self):
        row=self.rows()[0]
        for value,state in ((None,'null-fields'),(1,'invalid-fields'),('false','invalid-fields')):
            self.assertEqual(self.view({**row,'subscriptionsStopped':value})['state'],state)
        row.pop('subscriptionsStopped');self.assertEqual(self.view(row)['state'],'missing-fields')
        self.assertEqual(self.view({**self.rows()[0],'source':'future'})['state'],'unsupported-values')
    def test_u64_values_are_exact_and_boolean_or_overflow_are_rejected(self):
        row=self.rows()[1];self.assertEqual(self.view(row)['reported']['notificationSequence'],9007199254740995)
        for value in (True,-1,1<<64,1.5,'7'):
            self.assertEqual(self.view({**row,'notificationSequence':value})['state'],'invalid-fields')
        self.assertEqual(self.view({**row,'notificationSequence':(1<<64)-1})['reported']['notificationSequence'],(1<<64)-1)
    def test_command_completion_does_not_override_power_or_suspend(self):
        value=self.view(self.rows()[1]);self.assertTrue(value['reported']['commandCompleted']);self.assertFalse(value['reported']['publicPowerCurrent']);self.assertTrue(value['reported']['suspendRequested'])
        for i in (0,1):
            self.assertEqual(self.view({**self.rows()[i],'physicalSleepVerified':True})['state'],'contradictory')
    def test_stop_unknown_error_is_not_zero_or_known_failure(self):
        value=self.view(self.rows()[4]);self.assertIsNone(value['reported']['writeError']);self.assertEqual(value['fieldStates']['writeError'],'not-reported')
        row={**self.rows()[4],'reason':'zero-write-failed','writeError':5};value=self.view(row);self.assertEqual(value['state'],'reported-fields');self.assertEqual(value['reported']['writeError'],5)
        for error in (None,0,True,-1,1<<32):
            self.assertNotEqual(self.view({**row,'writeError':error})['state'],'reported-fields')
    def test_stop_phase_retry_and_settlement_conflicts_stay_visible(self):
        row=self.rows()[4]
        for fields in ({'retryInMs':0},{'ownershipRetained':False},{'zeroApiAccepted':True},{'hardwareStopObserved':True},{'writeError':5}):
            self.assertEqual(self.view({**row,**fields})['state'],'contradictory')
        value=self.view({**row,'phase':'awaiting-identity-event','retryInMs':0});self.assertEqual(value['reportedDisposition'],'reported-stop-awaiting-identity')
    def test_settled_zero_acceptance_is_separate_from_source_retirement(self):
        row={**self.rows()[4],'phase':'settled','ownershipRetained':False,'reason':'zero-api-accepted','zeroApiAccepted':True}
        value=self.view(row);self.assertEqual(value['reportedDisposition'],'reported-stop-settled');self.assertFalse(value['physicalOrResourceReturnProven'])
        row.update(reason='source-retired-or-power-gated',zeroApiAccepted=False);self.assertEqual(self.view(row)['state'],'reported-fields')
        row['zeroApiAccepted']=True;self.assertEqual(self.view(row)['state'],'contradictory')
    def test_fx_reason_paths_and_arbitrary_extra_payload_are_not_projected(self):
        row={**self.rows()[2],'path':'private-EXE','account':'private-account'}
        value=self.view(row);text=json.dumps(value);self.assertNotIn('private-',text);self.assertGreaterEqual(value['unprojectedFieldCount'],3)
        self.assertFalse(value['reported']['ok']);self.assertTrue(value['reported']['enabled'])
    def test_settings_repair_deactivation_flag_is_only_reported(self):
        value=self.view(self.rows()[3]);self.assertTrue(value['reported']['automaticHardwareDeactivated']);self.assertFalse(value['physicalOrResourceReturnProven'])
        for source in ('defaults-size-limit','primary','backup','defaults'):
            self.assertEqual(self.view({**self.rows()[3],'source':source})['state'],'reported-fields')
        self.assertEqual(self.view({**self.rows()[3],'archived':True})['state'],'invalid-fields')
    def test_bounded_summary_keeps_rows_and_reported_birth_without_pairing(self):
        import log_lane_audit as m
        rows=self.rows()*100
        value=m.native_finite_outcome_evidence([('native-lifecycle.log',list(enumerate(rows,1)),{})],7012)
        self.assertEqual(value['rowsObserved'],500);self.assertLessEqual(len(value['observations']),80);self.assertEqual(value['rowCountsByPidRelation'],{'currentPidMatch':500})
        self.assertFalse(value['uniqueOperationsOrFailuresCounted'] or value['physicalOrResourceReturnProven'])
        self.assertEqual(value['observations'][0]['writerProcessCreation100ns'],'134394066260992255')
    def test_exact_events_and_native_root_members_only(self):
        import log_lane_audit as m
        self.assertIsNone(self.view({**self.rows()[0],'event':'gyro-power-early-pause-completed-future'}))
        for filename in ('nested/native-lifecycle.log','native-lifecycle.log.future','unrelated.log'):
            self.assertEqual(m.native_finite_outcome_evidence([(filename,[(1,self.rows()[0])],{})],7012)['rowsObserved'],0)
    def test_own_zip_summary_uses_original_common_evidence_path_and_raw_bytes(self):
        import log_lane_audit as m
        import tempfile,zipfile
        from pathlib import Path
        payload=('\n'.join(json.dumps(row) for row in self.rows())+'\n').encode()
        with tempfile.TemporaryDirectory() as tmp:
            p=Path(tmp)/'owned.zip'
            with zipfile.ZipFile(p,'x') as z:z.writestr('native-lifecycle.log',payload)
            result=m.audit_zip(p,{'baseEvents':list(m.FINITE_NATIVE_EVENTS)})
            view=result['commonEvidence']['nativeFiniteOutcomeEvidence']
            self.assertEqual(view['rowsObserved'],5);self.assertFalse(view['currentBusinessSuccessInferred'])
            with zipfile.ZipFile(p) as z:self.assertEqual(z.read('native-lifecycle.log'),payload)
    def test_new_boolean_fields_reject_number_and_string_substitutes(self):
        for index,key in ((0,'subscriptionsStopped'),(1,'commandCompleted'),(2,'ok'),(3,'automaticHardwareDeactivated'),(4,'legacyPathless')):
            for value in (0,1,'false'):
                self.assertEqual(self.view({**self.rows()[index],key:value})['state'],'invalid-fields')

class CalibrationRestoreEvidenceTests(unittest.TestCase):
    def test_native_fusion_resident_reason_is_bound_to_valid_wait_and_reported_in_detail(self):
        from log_lane_audit import CALIBRATION_WAIT_RESIDENT_REASONS, calibration_restore_lane_state
        context = dict(schema=1, sourceScope='scoped-frame', bindingGeneration='7', choiceGeneration='8',
                       sessionStartSteadyTicks='42', recheckReason='fusion-session-changed')
        base = self.row(restoreContext=context)
        witnesses = [dict(base, calibrationWaitResidentReasonV1=reason) for reason in CALIBRATION_WAIT_RESIDENT_REASONS]
        valid = witnesses[0]
        for bad in (dict(valid, calibrationSessionWaitSample=True), dict(valid, calibrationWaitResidentReasonV1=True),
                    dict(valid, calibrationWaitResidentReasonV1=[]), dict(valid, loaded=True),
                    dict(valid, restoreContext=None), dict(valid, event='gyro-calibration-restored')):
            self.assertEqual(calibration_restore_lane_state(bad), 'unverified-marker')
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / 'wait.zip'
            with zipfile.ZipFile(path, 'w') as archive:
                for member in ('native-lifecycle.log', 'native-detail.log'):
                    archive.writestr(member, ''.join(json.dumps(r)+'\n' for r in witnesses))
            report = audit_zip(path, {'baseEvents': [base['event']]})
        self.assertEqual([(f['kind'], f['file'], f['exampleLines']) for f in report['violations']],
                         [('gyro-calibration-resident-in-native-detail', 'native-detail.log', list(range(1, 7)))])
        for member in report['files']:
            if member['file'] in ('native-lifecycle.log', 'native-detail.log'):
                coverage = member['calibrationRestoreLaneCoverage']['events'][base['event']]['reported-resident-fusion-wait']
                self.assertEqual(coverage['residentReasons'], dict.fromkeys(CALIBRATION_WAIT_RESIDENT_REASONS, 1))

    def test_calibration_lane_coverage_distinguishes_ineligible_receipts_and_unmarked_waits(self):
        context = dict(schema=1, sourceScope='scoped-frame', bindingGeneration='7', choiceGeneration='8',
                       sessionStartSteadyTicks='42', recheckReason='fusion-session-changed')
        wait = self.row(restoreContext=context)
        first = dict(wait, restoreContext=dict(context, recheckReason='first-recipe'))
        capture_owner = dict(wait, restoreContext=dict(context, sourceScope='capture-owner-observation', choiceGeneration=None))
        sample = dict(wait, calibrationSessionWaitSample=True)
        contradictory = dict(first, calibrationSessionWaitSample=True)
        source = self.row('gyro-calibration-awaiting-current-source', sourceCurrent=False, calibrationOwner='none')
        restored = self.row('gyro-calibration-restored', loaded=True, confidence=.99, weight=12)
        event = wait['event']
        rows = [wait, first, capture_owner, sample, contradictory, self.row(), source, restored,
                {'kind': event}, dict(wait, restoreContext=None)]
        physical = [json.dumps(row).encode() + b'\r\n' for row in rows]
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / 'calibration.zip'
            with zipfile.ZipFile(path, 'w') as archive:
                for member in ('native-lifecycle.log.1', 'native-detail.2.log', 'nested/native-detail.log'):
                    archive.writestr(member, b''.join(physical))
            result = audit_zip(path, {'baseEvents': list({row['event'] for row in rows if 'event' in row})})
        seen = {(r['kind'], r['file'], r['event']): r['exampleLines'] for r in result['violations']}
        self.assertEqual(seen, {
            ('known-detail-in-native-low', 'native-lifecycle.log.1', event): [4],
            ('gyro-calibration-resident-in-native-detail', 'native-detail.2.log', event): [2, 3],
            ('gyro-calibration-resident-in-native-detail', 'native-detail.2.log', source['event']): [7],
            ('gyro-calibration-resident-in-native-detail', 'native-detail.2.log', restored['event']): [8],
        })
        coverage = [entry['calibrationRestoreLaneCoverage'] for entry in result['files']
                    if 'calibrationRestoreLaneCoverage' in entry]
        self.assertEqual(len(coverage), 2)
        expected = {'unmarked-scoped-fusion-wait': [1], 'resident-receipt': [2, 3],
                    'reported-detail-sample': [4], 'unverified-marker': [5], 'no-recheck-context': [6],
                    'unverified-receipt': [10]}
        for entry in coverage:
            self.assertEqual(entry['events'][event], {state: dict(rows=len(lines), exampleLines=lines,
                bytes=sum(len(physical[line - 1]) for line in lines)) for state, lines in expected.items()})

    @staticmethod
    def row(event='gyro-calibration-awaiting-current-recipe',**fields):
        row={'event':event,'pid':71,'writerProcessCreation100ns':'134394066260992255','sourceQualified':True,'loaded':False,'weight':0,'confidence':0,'matrixId':'private-matrix','matrixSourceSha256':'private-digest','deviceId':'private-device'}
        row.update(fields);return row
    @staticmethod
    def view(row):
        from log_lane_audit import calibration_restore_record
        return calibration_restore_record(row)
    def test_restore_context_requires_exact_shape_without_inventing_identity(self):
        context = {'schema': 1, 'sourceScope': 'scoped-frame', 'bindingGeneration': '18446744073709551615',
                   'choiceGeneration': None, 'sessionStartSteadyTicks': '-9223372036854775808',
                   'recheckReason': 'calibration-owner-changed', 'unknown': 'private'}
        result = self.view(self.row(restoreContext=context))
        self.assertEqual(result['restoreContext'], {'state': 'reported-fields', 'reported': {
            key: value for key, value in context.items() if key not in ('schema', 'unknown')}})
        self.assertEqual(self.view(self.row())['restoreContext'], {'state': 'not-reported'})
        self.assertEqual(self.view(self.row(restoreContext=None))['restoreContext'], {'state': 'reported-null'})
        for key, value in [('bindingGeneration', True), ('bindingGeneration', '0'), ('choiceGeneration', '01'),
                           ('sessionStartSteadyTicks', '-0'), ('sessionStartSteadyTicks', str(1 << 63)),
                           ('sourceScope', 'future'), ('recheckReason', ['first-recipe'])]:
            with self.subTest(key=key, value=value):
                issue = self.view(self.row(restoreContext={**context, key: value}))
                self.assertEqual(issue['restoreContext'], {'state': 'invalid-fields', 'fieldIssues': [key]})
                self.assertEqual(issue['state'], 'reported-fields')
        invalid_scope = {**context, 'sourceScope': 'capture-owner-observation', 'choiceGeneration': '3'}
        self.assertEqual(self.view(self.row(restoreContext=invalid_scope))['restoreContext']['fieldIssues'], ['choiceGeneration'])
        self.assertEqual(self.view(self.row(restoreContext={**context, 'schema': True}))['restoreContext']['state'],
                         'unsupported-schema')
        legacy = {'event': 'gyro-calibration-restored', 'offset': {'x': 1, 'y': 2, 'z': 3}, 'weight': 4,
                  'confidence': 0.5, 'restoreContext': context}
        self.assertEqual(self.view(legacy)['restoreContext'], {'state': 'not-applicable'})

    def test_zip_restore_context_counts_rows_without_merging_equal_receipts(self):
        context = {'schema': 1, 'sourceScope': 'capture-owner-observation', 'bindingGeneration': '2',
                   'choiceGeneration': None, 'sessionStartSteadyTicks': '300', 'recheckReason': 'first-recipe'}
        reported = self.row(restoreContext=context)
        with tempfile.TemporaryDirectory() as temp:
            path = Path(temp) / 'restore.zip'
            with zipfile.ZipFile(path, 'w') as archive:
                archive.writestr('native-lifecycle.log.1', json.dumps(reported) + '\n')
                archive.writestr('native-lifecycle.log', ''.join(json.dumps(row) + '\n' for row in
                    (self.row(), reported, {**reported, 'loaded': True})))
            view = audit_zip(path, {'baseEvents': []})['commonEvidence']['calibrationRestoreEvidence']
        self.assertEqual(view['countsByRestoreContextState'], {'reported-fields': 3, 'not-reported': 1})
        self.assertEqual(view['countsByRecheckReason'], {'first-recipe': 2})
        self.assertEqual(view['rowsObserved'], 4)
        self.assertFalse(view['operationsPaired'])

